(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["multimodal"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-visual-instruction-tuning-2023"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-1\">一 · 一个真实在线服务的开场：图文问答的尾延迟从哪里来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-2\">二 · 旧方案的主流做法：冻结编码器 + 轻量投影 + 统一自回归解码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-3\">三 · 痛点一：KV cache 被视觉前缀长期占位，显存上限先于算力到顶</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-4\">四 · 痛点二：首 token 延迟被预填锁死，扩容解码吞吐无效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-5\">五 · 痛点三：量化误差沿跨模态注意力传导，精度策略无处落地</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-6\">六 · 为什么非改不可：接口层面的三个不可调和</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-7\">七 · 视觉前缀常驻显存：统一序列拼接在在线服务里的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-8\">八 · 把请求当成向量：负载的四元组与测量口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-9\">九 · 并发与批大小：视觉前缀如何压缩有效批</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-10\">十 · SLO 与长尾：首 token 延迟被谁吃掉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-11\">十一 · 负载反向塑造方案：分辨率、压缩与量化的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-12\">十二 · 容量规划的估算链与不可核验项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-13\">十三 · 视觉前缀的 kernel 切分：从 patch 网格到 MMA tile</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-14\">十四 · 数据类型选择：BF16 打底、FP8 试探、NVFP4 只给权重</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-15\">十五 · 累加精度与误差：FP32 累加器是底线，块缩放是变量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-16\">十六 · Blackwell 特性：tcgen05、TMEM 与 2-SM MMA 对视觉前缀的意义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-17\">十七 · 精度—显存—延迟的三方权衡：一个可执行的判断链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-18\">十八 · 视觉前缀的量化边界：投影层输出维度、KV 常驻与误差传导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-19\">十九 · 视觉前缀的显存账本：三段式结构里谁在占位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-20\">二十 · 分页与块管理：视觉前缀如何被切碎复用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-21\">二十一 · 压缩与卸载：在常驻项上做减法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-22\">二十二 · 带宽瓶颈的位置：预填吃算力，解码吃带宽</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-23\">二十三 · 可复算的显存预算：从结构参数到准入判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-24\">二十四 · 视觉前缀把批处理的不对称性放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-25\">二十五 · 连续批处理在视觉场景下的改造</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-26\">二十六 · chunked prefill：把视觉预填切开的边界在哪</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-27\">二十七 · 优先级、抢占与视觉 KV 的回收代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-28\">二十八 · 分离式预填/解码对视觉链路的特殊约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-29\">二十九 · 尾延迟的压法：把方差来源逐个钉住</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-30\">三十 · 视觉前缀分桶与抢占：连续批处理在多模态负载下的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-31\">三十一 · 视觉前缀把并行切分的账本改写</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-32\">三十二 · TP 与 EP：集合通信的两种代价曲线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-33\">三十三 · PP 与 DP：气泡与副本的不均衡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-34\">三十四 · NVLink 5 与 NVSwitch：域内带宽把瓶颈推到哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-35\">三十五 · NIXL 传输与 KV 的跨节点搬运</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-36\">三十六 · 通信瓶颈的判定与工程取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-37\">三十七 · 精度塌陷：从视觉 KV 到跨模态注意力的误差传导链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-38\">三十八 · OOM 的三种来源与显存账本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-39\">三十九 · 批抖动与尾延迟：方差才是敌人</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-40\">四十 · 静默降级：没有报错的失败</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-41\">四十一 · 监控面与定位路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-42\">四十二 · 工程判断：把失败模式写进准入与配置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-43\">四十三 · 视觉前缀的失效边界与可观测回滚</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-44\">四十四 · 口径先行：这份材料能登记什么、不能登记什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-45\">四十五 · 硬件档位与 batch/并发：为什么本文无法绑定 Blackwell 配置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-46\">四十六 · 指标定义：TTFT/TPOT/吞吐/显存/功耗各自被什么主导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-47\">四十七 · 哪些提升不可比：四类常见误读</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-48\">四十八 · 容量规划的可用算式与监控项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-49\">四十九 · 读数的落点：把“提升”还原为结构量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-50\">五十 · 视觉前缀的计量口径：哪些数字能横向读，哪些不能</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-51\">五十一 · 迁移到非冻结编码器时的接口重写</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-52\">五十二 · 迁到高分辨率与视频输入时的前缀膨胀</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-53\">五十三 · 迁到低精度与量化路径时的误差传导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-54\">五十四 · 迁到分离式预填/解码与多模态批调度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-55\">五十五 · 规模上限与不适用的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-visual-instruction-tuning-2023-sec-56\">五十六 · 迁移边界：视觉前缀方案在哪些模型与领域会失效</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:543px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 543.2 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">图像输入先做分辨率归一与分块预处理，得到固定网格的 patch 序列，…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">视觉编码器对 patch 序列做前向，输出逐 patch 特征图，该阶…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">投影层把视觉特征映射到语言模型嵌入空间，形成视觉 token 前缀并写…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">视觉 token 与文本指令 token 拼接为统一序列，跨模态注意力…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">自回归解码逐 token 生成回答，视觉 KV 常驻显存，批内不同请求…</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"461.2\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">服务侧按视觉 token 数量与文本长度做准入与分桶，控制单批 KV …</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-1\">一 · 一个真实在线服务的开场：图文问答的尾延迟从哪里来</h3>\n<p>设想一个面向客服的图文问答服务：用户上传一张商品破损照片并附一句“这个还能退吗”。请求进入网关后，预处理按既定分辨率把图像切成 patch 网格，视觉编码器前向得到逐 patch 特征，投影层把这些特征映射成与词表同维的视觉 token，写入 KV cache，随后文本指令 token 追加到序列尾部，解码器逐 token 生成回答。这条链路里，视觉 token 是<b>常驻前缀</b>：它们在整个解码生命周期内占据 KV cache 位置，不随文本增长而释放。于是同一批里，一个 4 字提问配一张高分辨率图，与一个 200 字长问配一张低分辨率图，KV 占用可能相差数倍，而调度器若按“请求数”而非“视觉 token 数”分桶，短请求会被长请求拖住，尾延迟由批内最长前缀决定。</p>\n<p>更具体的痛点在于预填阶段。跨模态注意力在解码器每一层都要读取视觉 KV，而预填必须一次性处理全部视觉 token——这部分算力与文本长度无关，只与分辨率决定的 patch 网格规模成正比。首 token 延迟因此被视觉编码前向与预填主导，而非被解码步数主导。工程上这意味着：扩容解码吞吐的常规手段（增大批、提高并发）对首 token 延迟几乎无效，因为瓶颈在预填的算力峰值与 KV 写入带宽上。公式上，视觉 token 序列与文本序列拼接后进入解码：</p>\n<div class=\"formula\">$$\\mathbf{H}_{v}=\\mathrm{Proj}\\big(\\mathrm{Enc}(\\mathbf{X}_{\\mathrm{img}})\\big),\\quad \\mathbf{z}_{t}=\\mathrm{LM}\\big([\\mathbf{H}_{v};\\mathbf{H}_{\\mathrm{txt}}]_{&lt;t}\\big)$$</div>\n<p>其中 $\\mathbf{H}_{v}$ 的长度由 patch 网格决定，$\\mathrm{Proj}$ 的输出维度决定每个视觉 token 在 KV cache 中的单 token 显存增量。两者相乘就是单请求的视觉 KV 常驻占用。分辨率翻倍，patch 数按平方增长，KV 占用与预填算力同步抬升——这是旧方案非改不可的第一个硬约束。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-2\">二 · 旧方案的主流做法：冻结编码器 + 轻量投影 + 统一自回归解码</h3>\n<p>这篇论文之前，多模态推理栈的主流做法可以概括为三段式：冻结的视觉编码器输出 patch 级特征，一个轻量投影层把特征对齐到语言模型词嵌入空间，然后与文本 token 拼接成统一序列送入自回归解码器。跨模态注意力不在编码器侧完成，而是在解码器内部各层读取视觉 KV 与文本 KV。这套做法的工程吸引力在于<b>复用</b>：解码器结构不改，KV cache 机制不改，批调度器只需把视觉 token 当作序列前缀管理，而不必为多模态单独造一套推理引擎。</p>\n<p>但“复用”的代价是把视觉 token 变成一等公民的同时，也把它的全部开销塞进了语言模型的既有瓶颈里。旧方案的推理栈没有内置视觉 token 压缩或合并机制：编码器输出多少 patch，投影层就产出多少视觉 token，一个不少地写入 KV cache。高分辨率输入下，前缀长度无法从内部约束，只能靠外部策略（降分辨率、裁剪、分块）间接控制。这就形成了一个结构性矛盾：服务侧希望提高分辨率以保住细粒度视觉信息（破损位置、文字标签），而推理侧的分辨率每升一档，KV 占用与预填算力就线性甚至平方级上升。材料未给出具体规模数字，但这条线性关系本身足以让容量规划失去余量。</p>\n<table class=\"mini\"><thead><tr><th>链路阶段</th><th>决定因素</th><th>推理系统代价</th></tr></thead><tbody><tr><td>预处理分块</td><td>分辨率档位、patch 网格</td><td>直接决定视觉 token 数，是容量规划的主旋钮</td></tr><tr><td>视觉编码前向</td><td>patch 序列长度</td><td>纯视觉算力，与文本长度无关，构成首 token 延迟下界</td></tr><tr><td>投影层映射</td><td>输出维度</td><td>决定单视觉 token 的 KV 显存增量</td></tr><tr><td>预填与解码</td><td>视觉 KV 常驻 + 文本长度</td><td>跨模态注意力算力、KV 带宽、批内长度方差</td></tr></tbody></table>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-3\">三 · 痛点一：KV cache 被视觉前缀长期占位，显存上限先于算力到顶</h3>\n<p>旧方案里最容易被低估的是显存。文本 KV 随解码逐步增长，请求结束后整块回收；视觉 KV 则在预填阶段一次性写满并全程常驻，直到请求生命周期结束才释放。这意味着单请求的显存占用在时间轴上是一条“先跳升、后平台”的曲线，而不是文本请求那种缓慢爬升。服务侧按并发数做准入时，若只看平均序列长度，就会在图文混批时严重低估峰值占用。</p>\n<p>伪代码层面，准入控制的正确写法应按视觉 token 数分桶，而非按请求数：</p>\n<div class=\"formula\">$$\\text{KV}_{\\text{req}} \\approx N_{v}\\cdot d_{\\text{proj}}\\cdot L\\cdot b + N_{\\text{txt}}\\cdot d_{\\text{model}}\\cdot L\\cdot b$$</div>\n<p>其中 $N_{v}$ 为视觉 token 数，$d_{\\text{proj}}$ 为投影层输出维度，$L$ 为解码器层数，$b$ 为每元素字节数。第一项在解码全程不变，第二项随生成增长。调度器若把两类请求混批，批内最长视觉前缀决定了整批的 KV 峰值，短请求被迫为长请求的视觉前缀买单——这就是显存碎片与尾延迟的来源。工程判断很直接：视觉前缀长度方差大的负载，必须按 $N_{v}$ 分桶并限制单批视觉 token 总量，否则显存上限会先于算力到顶。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-4\">四 · 痛点二：首 token 延迟被预填锁死，扩容解码吞吐无效</h3>\n<p>第二个非改不可的理由是延迟结构。旧方案的首 token 延迟由视觉编码前向与预填阶段主导：编码器要对整个 patch 网格做前向，预填要把全部视觉 token 写入 KV 并完成各层跨模态注意力。这两段的算力峰值与分辨率绑定，与并发数无关。服务侧常见的扩容手段——加副本、提并发、增大批——优化的是解码阶段的吞吐，对首 token 延迟几乎没有帮助。当 SLO 写的是“首 token 在若干毫秒内返回”时，旧方案的可调空间只剩下降分辨率或减少视觉 token，而这两者都直接损伤回答质量。</p>\n<p>更麻烦的是批内干扰。解码阶段视觉 KV 不再变化但持续占位，跨模态注意力每步都要读取它，KV 带宽成为解码步的固定成本。批内若混入视觉前缀极长的请求，整批的每步注意力读取量被抬高，短请求的 token 间延迟（TPOT）被拉长。这与纯文本连续批处理的直觉相反：文本请求的 KV 随生成增长，调度器可以用“已生成长度”做公平性调节；视觉前缀是<b>预置常量</b>，无法通过抢占或分片削减，只能靠分桶隔离。旧方案没有为这种常量前缀设计调度原语，于是尾延迟在多模态混批下必然恶化。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-5\">五 · 痛点三：量化误差沿跨模态注意力传导，精度策略无处落地</h3>\n<p>第三个结构性问题是数值精度。旧方案把视觉 KV 与文本 KV 放在同一套 KV cache 里管理，量化若作用于 KV 或投影层权重，误差不会停留在视觉侧，而是通过解码器各层的跨模态注意力传导到最终输出。视觉 token 是投影层输出的连续向量，其数值分布与词嵌入不同，直接套用面向语言模型的低精度方案（如对 KV 做统一 scale 的量化）会削弱跨模态对齐，而材料未给出精度档位与误差数据，工程上无法从论文侧核验哪一档安全。</p>\n<p>这条链路的代价是隐性的：量化省下的是 KV 显存与带宽，付出的是跨模态注意力输出的稳定性，而后者在服务侧表现为回答质量漂移，难以用延迟指标捕获。旧方案的接口设计没有为“视觉 KV 单独一套精度策略”留出位置——投影层输出维度与视觉 KV 的量化粒度未被显式建模，导致精度决策只能在整块 KV cache 层面做，粒度太粗。这正是后续工作需要把视觉 token 当作可独立管理的序列前缀、而非普通文本 token 的根本原因。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-6\">六 · 为什么非改不可：接口层面的三个不可调和</h3>\n<p>把上述痛点收拢，旧方案在推理接口上有三处不可调和。其一，<b>长度不可控</b>：视觉 token 数由外部预处理分辨率决定，推理栈内部没有压缩或合并的钩子，容量规划只能被动接受输入侧的旋钮。其二，<b>生命周期不匹配</b>：视觉 KV 是常量前缀，文本 KV 是增量后缀，两者共用一套按请求生命周期分配的 KV 块，导致分桶、抢占、回收策略无法分别优化。其三，<b>精度粒度不匹配</b>：跨模态注意力的数值敏感度与纯文本注意力不同，但旧方案只提供整块 KV 的量化开关。</p>\n<p>这三点共同指向一个工程判断：多模态推理的性能上限不在解码器本身，而在视觉 token 作为序列前缀的管理方式上。论文确立的“视觉 token 一等公民”范式，其真正价值是把这个前缀暴露为可压缩、可合并、可批调度的接口——投影层输出维度决定单 token 显存增量，patch 网格决定前缀长度，两者都是可以在推理侧显式建模的量。后续的视觉 token 压缩、多模态量化与按前缀长度分桶的调度，都是围绕这三个量做文章。在材料未给出任何吞吐与精度数字的前提下，唯一能确定的是：只要视觉 KV 仍以常量前缀形式全程常驻，显存与首 token 延迟的线性关系就不会自己消失。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-7\">七 · 视觉前缀常驻显存：统一序列拼接在在线服务里的边界</h3>\n<p>一条图文请求进入服务后的固定开销，来自它把图像变成一段不可回收的序列前缀：预处理按设定分辨率切出 patch 网格，编码器前向产出逐 patch 特征，投影层把这些特征映射为与词表同维的视觉 token 并写入 KV cache，随后文本指令 token 才追加到序列尾部。关键代价是这段视觉 KV 在请求整个生命周期内常驻显存、不随解码推进而释放，于是单请求显存占用近似为 <span class=\"formula\">$$M_{\\text{req}}\\approx s_v\\cdot d\\cdot L\\cdot b_{\\text{kv}}+s_t\\cdot d\\cdot L\\cdot b_{\\text{kv}}$$</span> 其中 <span class=\"formula\">\\(s_v\\)</span> 为视觉 token 数、<span class=\"formula\">\\(s_t\\)</span> 为文本长度、<span class=\"formula\">\\(d\\)</span> 为投影层输出维度、<span class=\"formula\">\\(L\\)</span> 为解码器层数、<span class=\"formula\">\\(b_{\\text{kv}}\\)</span> 为每元素字节数。投影层输出维度直接决定单 token 的显存增量，而分辨率决定 <span class=\"formula\">\\(s_v\\)</span>——两者相乘就是无法用批调度摊薄的那部分固定成本。</p>\n<p>这套拼接方案在两类负载上失效得最明显。其一是高分辨率输入：分辨率上升使视觉 token 数线性膨胀，预填阶段要一次性处理全部视觉 token，首 token 延迟被视觉编码前向与预填算力峰值主导，而解码阶段这些 KV 仍占着位置却不产生新信息。其二是批内图文长度差异大的混合流量：若把短文本请求与长视觉前缀请求混批，显存分配被最长前缀拉齐，短请求的 KV 块被闲置，形成碎片并抬高尾延迟。工程上必须按视觉 token 数分桶准入，把 <span class=\"formula\">\\(s_v\\)</span> 相近的请求放进同一批，代价是调度器要维护前缀长度直方图、批利用率下降，吞吐让位于尾延迟约束。</p>\n<p>更隐蔽的边界在数值侧。该范式未内置视觉 token 压缩或合并机制，控制前缀长度只能靠外部策略；而一旦把量化施加到视觉 KV 或投影层权重，误差会经跨模态注意力传导到输出，材料未给出精度档位与误差数据，因此低精度方案的稳定性无法从论文本身核验。一个具体判断是：当单请求视觉前缀已占据显存预算的可观比例时，继续靠加批提高吞吐会先撞上显存上限而非算力上限，此时应优先压低 <span class=\"formula\">\\(s_v\\)</span> 或 <span class=\"formula\">\\(d\\)</span>，而不是调大批尺寸。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统代价</th><th>工程应对</th></tr></thead><tbody><tr><td>高分辨率输入</td><td>预填算力峰值与首 token 延迟上升，视觉 KV 常驻</td><td>限制分辨率档位、外接前缀压缩</td></tr><tr><td>批内前缀长度方差大</td><td>显存碎片、批利用率下降、尾延迟恶化</td><td>按视觉 token 数分桶准入</td></tr><tr><td>低精度量化视觉 KV</td><td>跨模态注意力输出偏差，材料未给误差数据</td><td>保留投影层高精度、单独监控对齐指标</td></tr></tbody></table>\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-8\">八 · 把请求当成向量：负载的四元组与测量口径</h3>\n<p>在视觉指令跟随的推理链路上，一个请求的负载特征不能只用“QPS”概括。它至少是四元组：视觉 token 数 <em>N<sub>v</sub></em>、文本 token 数 <em>N<sub>t</sub></em>、输出 token 数 <em>N<sub>o</sub></em>、以及到达时刻的并发上下文。前三个量直接决定单请求的 KV 占位与算力，第四个决定批调度能否把它们拼成有意义的批次。视觉 token 数由预处理分辨率与 patch 网格决定，分辨率上升线性抬高 <em>N<sub>v</sub></em>，因此分辨率档位本身就是负载参数，而不是“预处理细节”。</p>\n<p>可核查的测量口径要落到三个可采集量上。第一是<b>视觉前缀长度直方图</b>：按 <em>N<sub>v</sub></em> 分桶统计请求占比，桶宽取 patch 网格的整数倍，避免把同一分辨率档位拆散。第二是<b>批内长度方差</b>：对每个调度批次记录 <em>N<sub>v</sub></em>+<em>N<sub>t</sub></em> 的最大值与均值之比，这个比值直接对应显存碎片与尾延迟。第三是<b>预填耗时分解</b>：把首 token 延迟拆成视觉编码前向、投影层映射、视觉 KV 写入、文本预填四段，分别计时。没有这三项，任何“吞吐提升了多少”的说法都无法归因。</p>\n<p>单请求的 KV 占位可以写成显式式子，用于容量估算而非性能结论：</p>\n<div class=\"formula\">$$M_{\\mathrm{kv}} \\approx 2 \\cdot L \\cdot d_{\\mathrm{emb}} \\cdot b_{\\mathrm{bytes}} \\cdot (N_{v} + N_{t} + N_{o})$$</div>\n<p>其中 <em>L</em> 为解码器层数，<em>d</em><sub>emb</sub> 为投影层输出维度（与词嵌入同维），<em>b</em><sub>bytes</sub> 为每元素字节数。视觉 token 与文本 token 在这一式子里同权，这正是该范式的关键：视觉前缀不是“额外开销”，而是与文本共享同一 KV 池的常驻占位。工程含义是，<em>N<sub>v</sub></em> 的分布右尾比均值更重要——一个高分辨率请求可能顶掉数个低分辨率请求的显存预算。</p>\n<p>具体例子：同一服务同时接收 224 网格与更高分辨率档位的图像，前者视觉 token 少、预填短，后者视觉 token 成倍增长、预填阶段一次性处理全部视觉 token。若按 FIFO 混批，一个高分辨率请求进入批次就会把整批的预填算力峰值抬高，首 token 延迟被它主导，而低分辨率请求本可以更早返回。测量上应记录“批次内最大 <em>N<sub>v</sub></em> 请求的预填耗时占批次总预填耗时的比例”，这个比例高就说明混批策略在拖尾。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-9\">九 · 并发与批大小：视觉前缀如何压缩有效批</h3>\n<p>文本 LLM 的连续批处理假设批内序列长度相近，靠 token 级调度填满算力。视觉前缀打破了这个假设：<em>N<sub>v</sub></em> 在请求到达时已固定，不能像解码 token 那样逐步增长，于是批的显存占用在预填结束时就跳到峰值，之后解码阶段只增不减。有效批大小因此不是由算力上限决定，而是由 KV 池容量除以批内最大单请求占位决定。用式子表达准入约束：</p>\n<div class=\"formula\">$$\\sum_{i \\in \\mathcal{B}} M_{\\mathrm{kv}}^{(i)} \\le M_{\\mathrm{pool}}, \\quad \\text{且} \\quad \\max_{i \\in \\mathcal{B}} T_{\\mathrm{prefill}}^{(i)} \\le \\tau_{\\mathrm{ttft}}$$</div>\n<p>第一个约束是显存，第二个是首 token 延迟 SLO。<em>T</em><sub>prefill</sub> 由视觉编码前向与预填阶段主导，与 <em>N<sub>v</sub></em> 近似线性。两条约束联立后，高 <em>N<sub>v</sub></em> 请求会同时挤压批大小和延迟预算，形成“大图请求既占显存又占时间”的双重挤压。工程上可行的做法是按 <em>N<sub>v</sub></em> 分桶，桶内批大小固定，桶间独立排队；代价是低 <em>N<sub>v</sub></em> 桶可能因请求稀疏而批不满，牺牲一部分吞吐换尾延迟稳定。</p>\n<p>并发层面还要区分“在途请求数”与“可调度请求数”。视觉编码前向是纯视觉算力、与文本长度无关，若把它放在调度循环内同步执行，编码阶段会阻塞批调度，使解码批出现空泡。测量口径应记录编码阶段占用的时间片比例，以及该时间段内解码批的平均占用率。若编码与解码共享同一执行流，占用率下降就是可观测的吞吐损失；若采用分离式预填/解码（该主题另有片段展开），则要记录视觉编码与文本预填是否被切到不同资源池，以及跨池传输视觉 KV 的带宽代价。</p>\n<p>具体例子：一个批次里 6 个低分辨率请求加 1 个高分辨率请求，后者视觉 token 数倍于前者。按总显存约束，这个批次可能只能容纳 4 个低分辨率请求加 1 个高分辨率请求，有效批从 7 降到 5，而高分辨率请求的预填又拉长整批首 token 延迟。分桶后，高分辨率桶单独成批，低分辨率桶保持较高批大小，两桶的尾延迟都可控，代价是高分辨率桶的批利用率偏低。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-10\">十 · SLO 与长尾：首 token 延迟被谁吃掉</h3>\n<p>多模态服务的 SLO 通常分两段：首 token 延迟（TTFT）与每输出 token 延迟（TPOT）。视觉前缀只影响前者，却能把前者推到主导地位。TTFT 的分解为视觉编码前向、投影层映射、视觉 KV 写入、文本预填、首个解码步。前三段与 <em>N<sub>v</sub></em> 相关，第四段与 <em>N<sub>t</sub></em> 相关，第五段与批内并发相关。可核查的口径是：对每个请求记录这五段的耗时，并按 <em>N<sub>v</sub></em> 桶计算 P50 与 P99 的差值。若 P99 与 P50 的差距主要落在视觉编码段，说明长尾来自图像分辨率分布而非调度；若落在文本预填段，说明长尾来自批内混入了长文本请求。</p>\n<p>长尾的另一个来源是<b>显存碎片</b>。视觉 KV 在请求生命周期内常驻，请求结束时才回收；若批内请求完成时间差异大，KV 池会出现“已释放但不可用”的碎片窗口。分桶调度能缓解，但不能消除，因为同一桶内输出长度 <em>N<sub>o</sub></em> 仍会分化。测量口径应记录 KV 池的瞬时占用率与“最大可分配连续块”的比值，这个比值下降就是碎片化的直接证据。工程判断是：当碎片比值低于阈值时，宁可降低批大小也要保持可分配块的连续性，否则新到达的高 <em>N<sub>v</sub></em> 请求会被拒绝或排队，尾延迟进一步恶化。</p>\n<p>具体例子：两个请求视觉 token 相同但输出长度差异大，短输出请求先完成并释放 KV，长输出请求仍占着视觉前缀。此时 KV 池出现一个与短请求等大的空洞，但新请求的视觉前缀大于该空洞，无法填入，只能等待或触发重排。这类长尾不是算力不足，而是分配策略与负载形态不匹配；测量上表现为“池占用率不高但准入失败率上升”，是容量规划最容易误判的信号。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-11\">十一 · 负载反向塑造方案：分辨率、压缩与量化的取舍</h3>\n<p>负载形态不只被动影响调度，它反过来限定方案边界。分辨率档位是服务侧可配置的旋钮，但一旦对外承诺了图像质量，就不能随意下调；于是控制 <em>N<sub>v</sub></em> 的手段只剩视觉 token 压缩与合并（该主题在其他片段展开，此处只谈它对负载分布的影响）。压缩会改变 <em>N<sub>v</sub></em> 的分布形状：若压缩比对高分辨率图更强，右尾被削短，分桶的桶数可以减少，批大小上限提高；若压缩比对所有图一致，分布整体左移但形状不变，调度策略无需改动。测量口径应记录压缩前后 <em>N<sub>v</sub></em> 直方图的右尾分位点变化，而不是只报平均压缩比。</p>\n<p>量化作用于视觉 KV 或投影层权重时，会改变 <em>b</em><sub>bytes</sub>，从而线性改变 <em>M</em><sub>kv</sub>。但量化误差会传导到跨模态注意力输出，材料未给出精度档位与误差数据，因此不能把“低精度一定更省”当作默认判断。可核查的做法是：在固定负载分布下，分别测量不同精度档位的 TTFT、KV 占用与输出一致性指标（如与高精度输出的 token 重合率），把三者放在同一张表里权衡。若一致性指标下降而 TTFT 收益有限，说明该负载下量化不是有效旋钮。</p>\n<table class=\"mini\"><thead><tr><th>负载参数</th><th>影响的系统量</th><th>可核查口径</th><th>方案反向约束</th></tr></thead><tbody><tr><td>预处理分辨率</td><td><em>N<sub>v</sub></em>、KV 占位、预填算力</td><td>视觉 token 直方图右尾分位</td><td>对外图像质量承诺限制下调空间</td></tr><tr><td>批内长度方差</td><td>显存碎片、尾延迟</td><td>批次内最大/均值比、准入失败率</td><td>分桶降低批利用率</td></tr><tr><td>输出长度分布</td><td>KV 常驻时长、碎片窗口</td><td>池占用率与最大连续块比值</td><td>回收策略需与输出长度匹配</td></tr><tr><td>量化精度档位</td><td><em>b</em><sub>bytes</sub>、跨模态对齐</td><td>TTFT、KV 占用、输出重合率</td><td>误差数据缺失时不可默认启用</td></tr></tbody></table>\n<p>具体例子：服务把分辨率档位从一档提高到更高档，视觉 token 数上升，KV 占位与预填算力同步上升。若不同时调整分桶边界，原本的低分辨率桶会混入中等分辨率请求，批内方差变大，尾延迟恶化。正确做法是把桶边界与分辨率档位对齐，使每个桶内的 <em>N<sub>v</sub></em> 近似恒定，桶内只剩文本长度与输出长度的分化。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-12\">十二 · 容量规划的估算链与不可核验项</h3>\n<p>材料未给出吞吐、延迟、显存与精度数字，因此容量规划只能沿线性关系估算，不能报具体数字。估算链是：由 <em>N<sub>v</sub></em> 分布得到单请求 KV 占位的分布，由 KV 池容量得到每桶可容纳的并发数，由预填耗时与 SLO 得到每桶的批大小上限，两者取小即为该桶的有效并发。再把各桶的有效并发按请求占比加权，得到服务整体的稳态并发能力。这条链上每一步都可测量，唯独“预填耗时与 <em>N<sub>v</sub></em> 的比例系数”需要实测标定，不能从材料中推出。</p>\n<p>不可核验项要显式登记，避免被当成已知条件。第一，视觉编码器参数量与投影层维度未给出，<em>M</em><sub>kv</sub> 式子中的 <em>L</em> 与 <em>d</em><sub>emb</sub> 只能定性；第二，量化精度档位与误差数据未给出，精度取舍无法定量；第三，并发与 SLO 目标未给出，只能推断 TTFT 受视觉编码前向与预填阶段主导；第四，部署硬件档位未给出，无法绑定具体配置。工程判断是：在这些项缺失时，容量规划应给出区间而非点值，并把“视觉 token 数右尾”作为最敏感的输入变量做情景分析。</p>\n<p>具体例子：若请求占比中高 <em>N<sub>v</sub></em> 桶只占少数但单请求占位大，整体并发能力会被该桶的显存约束拉低，而平均口径看不出这一点。情景分析应分别计算“全部低分辨率”“混合分布”“右尾加重”三种负载下的有效并发，观察哪种情景先触达 SLO 边界。触达边界的那一档就是容量规划的安全上限，而不是平均值对应的上限。</p>\n<p>最后落在机制上：视觉 token 作为常驻 KV 前缀，使负载的右尾直接映射为显存与延迟的右尾；分桶调度、准入约束与分辨率档位对齐，是把这条映射变得可控的三个旋钮。任何一个旋钮缺失，负载分布的形状就会原样穿透到服务指标上，而测量口径的作用就是让这种穿透在数据上可见。</p>\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-13\">十三 · 视觉前缀的 kernel 切分：从 patch 网格到 MMA tile</h3>\n<p>视觉指令微调的推理链路里，编码器输出的 patch 特征经投影层变成视觉 token，这一段在 Blackwell 上并不是“一次大 GEMM”那么简单。投影层本质是一个 <em>N×d</em> 的线性映射（<em>N</em> 为视觉 token 数，<em>d</em> 为词嵌入维度），它与后续解码器的 QKV 投影共享同一套 Tensor Core 指令路径，但两者的 tile 形状差异极大：视觉前缀的 <em>N</em> 由预处理分辨率与 patch 网格决定，往往是一个不规整的数，而解码阶段的 GEMM 是 <em>1×d</em> 的瘦长形状。工程上的做法是把视觉前缀的投影与预填阶段的文本投影合并成一次大 GEMM，按 <em>M</em> 维（序列维）切 tile，让 tcgen05 的 MMA 指令在 <em>M</em> 方向连续吃满，避免为视觉 token 单独起一次 kernel launch。代价是预填阶段的一次性算力峰值被抬高：视觉 token 全部进入预填，首 token 延迟由这段 GEMM 与跨模态注意力的 prefill 共同主导，而不是由解码步决定。</p>\n<p>公式上，投影层输出为</p>\n<div class=\"formula\">$$\\mathbf{H}_{v}=\\mathbf{X}_{p}\\mathbf{W}_{p}+\\mathbf{b}_{p},\\quad \\mathbf{X}_{p}\\in\\mathbb{R}^{N\\times d_{e}},\\ \\mathbf{W}_{p}\\in\\mathbb{R}^{d_{e}\\times d}$$</div>\n<p>逐项看：<em>X<sub>p</sub></em> 是编码器逐 patch 特征堆叠后的矩阵，<em>N</em> 是视觉 token 数，<em>d<sub>e</sub></em> 是编码器输出维度；<em>W<sub>p</sub></em> 把 <em>d<sub>e</sub></em> 维压到词嵌入维 <em>d</em>。这个 GEMM 的算力是 <em>2N·d<sub>e</sub>·d</em>，而它写出的 <em>H<sub>v</sub></em> 每个 token 占 <em>d</em> 个元素，直接决定视觉 KV 的单 token 显存增量——<em>d</em> 越大，KV 每 token 越宽，KV cache 的字节数按 <em>N·d·层数·2（K 与 V）·字节宽度</em> 线性上涨。因此投影层输出维度不是“对齐一下就行”的超参，而是显存预算的直接乘数。</p>\n<p>具体例子：一张被切成 <em>16×16</em> patch 网格的图，若网格为 <em>24×24</em>，则 <em>N=576</em>；在 <em>d=4096</em>、BF16 存储下，单层单请求的视觉 KV 就是 <em>576×4096×2×2</em> 字节量级，乘以解码器层数后成为常驻显存的主体。批内若有若干张更高分辨率的图，<em>N</em> 成倍上升，预填 GEMM 的 <em>M</em> 维随之拉长，单批算力峰值与显存占用同步抬高——这正是按视觉 token 数分桶调度的物理依据。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-14\">十四 · 数据类型选择：BF16 打底、FP8 试探、NVFP4 只给权重</h3>\n<p>视觉前缀这条链路上，精度决策要分三处看：编码器输出、投影层权重、视觉 KV。编码器输出与投影层输入通常保持 BF16，因为跨模态对齐依赖特征动态范围，过早降到 FP8 会压缩视觉特征的尾部分布，误差经投影层放大后进入注意力。投影层权重可以走 FP8（E4M3），配合 per-tensor 或 per-channel scale，把 <em>W<sub>p</sub></em> 的存储减半、GEMM 吞吐提升；但激活侧仍留 BF16，形成 W8A16 的混合路径。视觉 KV 的量化则更敏感：K 与 V 在解码器各层被反复读取，量化误差会直接叠加到跨模态注意力输出上，材料未给出精度档位与误差数据，因此工程上应把视觉 KV 的量化当作独立开关，先在小批上做数值对照再放开。</p>\n<p>NVFP4 在 Blackwell 上的定位是权重侧的极致压缩：4 位块浮点配两级 scale（每 16 元素一个微块 scale，再加张量级全局 scale），适合投影层这种权重静态、激活动态的线性层。但视觉 KV 不适合 NVFP4——KV 是激活，逐 token 动态生成，块内动态范围不可控，4 位尾数会把跨模态注意力的 softmax 输入分布打散。判断标准很直接：权重可以离线校准 scale，激活不能，所以 NVFP4 只给 <em>W<sub>p</sub></em>，KV 留在 FP8 或 BF16。</p>\n<p>代价核算：把 <em>W<sub>p</sub></em> 从 BF16 降到 FP8，投影层 GEMM 的权重带宽减半，预填阶段这段 GEMM 的耗时随之下降，但它在总首 token 延迟里只占一部分，收益被编码器前向与注意力 prefill 稀释；把视觉 KV 降到 FP8，KV cache 字节数减半，直接抬高单卡可容纳的并发视觉前缀数，这是吞吐侧更实在的收益。误差传导路径是：<em>W<sub>p</sub></em> 量化误差 → <em>H<sub>v</sub></em> 偏移 → 视觉 KV 偏移 → 每层注意力输出偏移，逐层累积，因此投影层量化必须配校准集覆盖典型图像分布，而不是拿文本校准集凑数。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-15\">十五 · 累加精度与误差：FP32 累加器是底线，块缩放是变量</h3>\n<p>Tensor Core 的乘加在低精度输入下仍以 FP32 累加，这是数值稳定的底线。对视觉前缀的投影 GEMM，累加精度的影响体现在 <em>K</em> 维（即 <em>d<sub>e</sub></em>）的长度上：<em>d<sub>e</sub></em> 越大，FP16 累加的舍入误差累积越明显，BF16 输入配 FP32 累加是常规配置。真正引入新变量的是块缩放格式：FP8 与 NVFP4 都带 per-block scale，scale 本身的量化误差与反量化时的乘法会引入额外偏差，这部分偏差不随 <em>K</em> 维平均而消失，而是按块边界跳变。</p>\n<p>误差模型可以写成</p>\n<div class=\"formula\">$$\\hat{\\mathbf{H}}_{v}=\\sum_{k}\\big(s_{k}\\cdot q_{k}\\big)\\mathbf{W}_{p}[k,:]+\\varepsilon_{\\text{acc}},\\quad \\varepsilon_{\\text{acc}}\\sim\\mathcal{O}\\big(\\sqrt{d_{e}}\\cdot u\\big)$$</div>\n<p>逐项解释：<em>s<sub>k</sub></em> 是第 <em>k</em> 个块的缩放因子，<em>q<sub>k</sub></em> 是量化后的整数/浮点尾数，两者相乘还原出近似激活；<em>ε<sub>acc</sub></em> 是累加舍入误差，量级随 <em>√d<sub>e</sub></em> 与单位舍入 <em>u</em> 增长。关键在于 <em>s<sub>k</sub></em> 的选取：块越小，scale 越贴合局部动态范围，但 scale 元数据开销越大；块越大，scale 越粗，块内尾部分布被同一 scale 压扁，误差在块边界处表现为系统性偏移。视觉特征的空间相关性使相邻 patch 的动态范围接近，因此视觉前缀的块缩放比文本侧更“友好”，但高对比度图像（强光、阴影交界）会打破这个假设。</p>\n<p>工程代价：块缩放元数据本身占带宽。以 FP8 per-128-element 块为例，每 128 个元素附一个 FP32 scale，元数据带宽占比虽小，但在视觉前缀这种 <em>N</em> 大、<em>K</em> 中等的 GEMM 上会稀释有效带宽利用率；NVFP4 的 16 元素微块把元数据占比推得更高，只有在权重侧、且 GEMM 足够大时才划算。具体例子：投影层若 <em>d<sub>e</sub>=1024</em>、<em>d=4096</em>，权重矩阵 <em>4M</em> 元素，NVFP4 下微块 scale 数量是元素数的 <em>1/16</em>，这部分元数据要随权重一起驻留显存并被反复读取，收益必须用端到端预填耗时来核算，而不是只看权重字节数。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-16\">十六 · Blackwell 特性：tcgen05、TMEM 与 2-SM MMA 对视觉前缀的意义</h3>\n<p>tcgen05 是 Blackwell 第五代 Tensor Core 的指令族，其关键变化是把累加器从寄存器文件搬到 Tensor Memory（TMEM）。对视觉前缀的投影 GEMM，这意味着 MMA 的累加结果不再占用寄存器堆，寄存器压力释放后可以同时挂更多 tile、更深地流水预取权重；TMEM 的容量与带宽成为新的约束点，tile 划分要按 TMEM 容量反推，而不是按寄存器数反推。工程上的直接后果是：预填阶段那段大 GEMM 可以维持更高的 MMA 占用率，视觉 token 的 <em>M</em> 维越长，tcgen05 的流水越能摊薄指令发射开销。</p>\n<p>2-SM MMA（两 SM 协同执行一次 MMA）把一对 SM 的 Tensor Core 与 TMEM 联合起来，等效于把 MMA tile 在 <em>N</em> 或 <em>K</em> 方向加倍。对投影层这种 <em>N</em> 不规整、<em>K=d<sub>e</sub></em> 固定的 GEMM，2-SM 模式适合在 <em>N</em> 方向拼接两个视觉前缀 tile，减少小 tile 的边界浪费；但它要求两个 SM 的 tile 形状匹配，视觉 token 数不能被 2 整除时会有尾块，尾块走单 SM 路径，形成负载不均。调度上应把视觉前缀按 2-SM tile 对齐切分，把余数集中到一个尾块，而不是让每个 tile 都带零头。</p>\n<p>代价面：2-SM MMA 抬高单次 MMA 的算力密度，但也抬高同步开销——两个 SM 的 TMEM 分配与屏障同步是显式的，若 tile 太小，同步开销吃掉算力收益。判断阈值是 tile 的 <em>K</em> 维深度：<em>d<sub>e</sub></em> 较小时（如 <em>768</em>），2-SM 的收益被同步摊薄；<em>d<sub>e</sub></em> 较大时（<em>1024</em> 以上）才值得启用。视觉编码器的输出维度决定了这个选择，而材料未给出具体配置，因此部署时应以实测预填耗时为准切换 1-SM/2-SM 路径，而不是默认全开。</p>\n<p>具体例子：预填阶段把视觉前缀与文本指令拼成一条长序列，跨模态注意力的 QK^T 与 PV 两个 GEMM 都走 tcgen05。视觉 KV 在 <em>K</em> 维上是常驻的，文本 token 的 Q 去读它，2-SM MMA 在 <em>N</em> 方向（文本 query 维）拼接可以提升注意力 GEMM 的占用率；但注意力的 softmax 在 FP32 上做，TMEM 里的累加结果要搬回寄存器做归约，这段搬运是固定开销，序列越长摊得越薄。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-17\">十七 · 精度—显存—延迟的三方权衡：一个可执行的判断链</h3>\n<p>把上述机制串成工程判断链：先定视觉 KV 的精度档位，因为它决定常驻显存与并发上限；再定投影层权重的精度，因为它只影响预填耗时；最后定累加与块缩放配置，因为它影响数值稳定性而非吞吐。顺序不能反——若先压权重精度再发现 KV 放不下，等于白做。</p>\n<p>量化收益的估算式可以写成</p>\n<div class=\"formula\">$$\\Delta T_{\\text{prefill}}\\approx\\frac{2N d_{e} d}{P_{\\text{eff}}}\\Big(1-\\frac{b_{w}}{b_{\\text{ref}}}\\Big),\\quad C_{\\text{KV}}\\propto N\\cdot d\\cdot L\\cdot \\frac{b_{\\text{kv}}}{b_{\\text{ref}}}$$</div>\n<p>逐项看：<em>ΔT<sub>prefill</sub></em> 是投影 GEMM 的耗时下降，<em>P<sub>eff</sub></em> 是有效算力，<em>b<sub>w</sub></em>/<em>b<sub>ref</sub></em> 是权重字节宽度之比；<em>C<sub>KV</sub></em> 是视觉 KV 容量，<em>L</em> 是层数，<em>b<sub>kv</sub></em>/<em>b<sub>ref</sub></em> 是 KV 字节宽度之比。两式的差别在于：权重精度只进第一式，KV 精度只进第二式，二者不可互相替代。视觉 token 数 <em>N</em> 同时出现在两式中，说明分辨率是唯一同时抬高算力与显存的旋钮——降分辨率比降精度更彻底，但会损失视觉细节，这是精度策略无法绕开的取舍。</p>\n<p>具体例子：同一批请求里，若把视觉 KV 从 BF16 降到 FP8，<em>C<sub>KV</sub></em> 减半，单卡可容纳的视觉前缀数翻倍，批调度可以放宽分桶粒度、减少尾延迟；代价是跨模态注意力输出的数值偏差，材料未给出误差数据，因此上线前必须在固定小批上做逐层输出对照，确认偏差不改变生成结果的语义走向。反之，把投影层权重降到 NVFP4 只缩短预填 GEMM，对常驻显存无贡献，若首 token 延迟已被编码器前向主导，这项优化的端到端收益接近于零。</p>\n<p>最后的工程判断落在监控项上：视觉 token 数、预填 GEMM 耗时、KV 字节占用、批内视觉前缀长度方差，这四项共同决定精度档位能否放开。视觉前缀长度方差大时，混批会让长前缀请求拖住短请求，此时即便 KV 精度减半也不应放宽分桶——显存碎片与尾延迟的代价会吃掉量化收益。精度策略必须与批调度策略联动评审，单独调精度档位在多模态服务里没有意义。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-18\">十八 · 视觉前缀的量化边界：投影层输出维度、KV 常驻与误差传导</h3>\n<p>视觉 token 一旦写入 KV cache 就全程常驻，因此单请求的 KV 显存增量可以写成 <span class=\"formula\">$$M_{\\text{kv}} \\approx 2 \\cdot L \\cdot d_{\\text{proj}} \\cdot N_{v} \\cdot b_{\\text{kv}}$$</span> 其中 L 是解码器层数、d_proj 是投影层输出维度（即词嵌入维度）、N_v 是视觉 token 数、b_kv 是每元素字节数，系数 2 对应 K 与 V 两份缓存。这个式子逐项解释了量化为什么是唯一能同时压缩 d_proj 与 b_kv 的旋钮：投影层输出维度由语言模型词嵌入固定，无法在推理侧改动，于是降低 b_kv 成为唯一可行的显存杠杆。代价是视觉 KV 与投影层权重一旦低精度化，误差会经每层跨模态注意力逐层叠加到输出 logits，而材料未给出任何精度档位与误差数据，因此这条链路的数值稳定性无法从材料核验，只能作为待测项登记。</p>\n<p>失效条件集中在预填阶段。视觉 token 在预填时被一次性全部处理，其算力峰值与 N_v 成正比，而解码阶段视觉 KV 只读不写。若把视觉 token 当作普通文本 token 混入同一批次，调度器会按平均序列长度估算预填开销，低估视觉前缀的算力峰值，首 token 延迟直接超标。工程上应按 N_v 分桶而非按总长度分桶，把高分辨率请求聚成独立批次，避免长短视觉前缀在同一批内互相拖累显存碎片。</p>\n<table class=\"mini\"><thead><tr><th>边界条件</th><th>机制后果</th><th>系统代价</th></tr></thead><tbody><tr><td>分辨率档位上调</td><td>N_v 线性增长，视觉 KV 常驻</td><td>显存占用与预填算力同步上升</td></tr><tr><td>视觉 KV 低精度化</td><td>误差传导至跨模态注意力</td><td>对齐质量不可核验，需精度回归</td></tr><tr><td>批内 N_v 方差大</td><td>显存碎片、尾延迟恶化</td><td>吞吐受最慢请求约束</td></tr></tbody></table>\n<p>具体例子：同一批次混入一张高分辨率图与若干纯文本请求，高分辨率请求的视觉前缀在预填时独占算力峰值，而文本请求的 KV 块被碎片化分配，结果是整批首 token 延迟由那张图决定、显存利用率由文本请求拉低。判断上，视觉前缀的量化收益必须与跨模态对齐的精度回归绑定评估；在缺少误差数据时，优先对视觉 KV 采用与文本 KV 一致的精度档位，把压缩空间留给外部视觉 token 合并策略，而不是在投影层权重上先行降精度。</p>\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-19\">十九 · 视觉前缀的显存账本：三段式结构里谁在占位</h3>\n<p>把一次图文请求拆成显存科目，账本只有三栏：权重、激活、KV cache。权重是静态的，视觉编码器、投影层、语言解码器三段各自常驻一份；激活是瞬态的，编码器前向的 patch 特征图与解码器逐层的中间张量在生命周期内短暂占用；KV cache 是随请求增长的，视觉 token 一旦写入便在整个解码过程中常驻。三者性质不同，容量规划必须分开算，混在一起谈“显存够不够”没有工程意义。</p>\n<p>关键在于视觉 token 的 KV 增量与文本 token 的 KV 增量共用同一套寻址结构。设视觉 token 数为 $N_v$，文本前缀长度为 $N_t$，解码器层数为 $L$，KV 头数为 $H_{kv}$，单头维度为 $d_h$，每元素字节数为 $b$，则单请求 KV 占用为：</p>\n<div class=\"formula\">$$M_{\\mathrm{KV}} = 2 \\cdot L \\cdot H_{kv} \\cdot d_h \\cdot b \\cdot (N_v + N_t + N_{gen})$$</div>\n<p>系数 2 来自 K 与 V 两份缓存。$N_{gen}$ 是解码过程中逐步追加的生成 token 数。这个式子的工程含义是：$N_v$ 不是“前缀里的一段”，而是与文本 token 完全等价地占据 KV 位置，且因为它在预填阶段一次性写入、在解码阶段不再变化，它对显存的贡献是“只增不减的常驻项”。文本 token 的 KV 随生成推进继续增长，视觉 KV 则是请求生命周期内的固定底座。</p>\n<p>投影层输出维度直接决定单 token 增量：$\\mathrm{Proj}$ 把视觉特征映射到词嵌入维度，该维度与 $H_{kv}\\cdot d_h$ 对齐后，每个视觉 token 的 KV 字节数就固定下来。分辨率上升使 patch 网格变密，$N_v$ 线性增长，$M_{\\mathrm{KV}}$ 随之线性增长——这是本范式中最硬的线性关系，也是容量规划唯一可以据实推算的抓手。材料未给出编码器参数量、投影层维度与层数，因此具体字节数无法落数，但结构关系是确定的。</p>\n<p>一个具体例子：同一张图在低分辨率档位下产生较少的 patch，视觉前缀短，单请求 KV 底座小，批内可以塞进更多请求；切换到高分辨率档位，$N_v$ 成倍上升，KV 底座同步成倍上升，原本能混批的请求被迫拆批。此时若仍按文本长度分桶，就会把视觉前缀长的请求和短的混在一起，长请求的 KV 底座拖住整批的显存水位。工程判断是：分桶键必须包含 $N_v$，不能只看 $N_t$。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-20\">二十 · 分页与块管理：视觉前缀如何被切碎复用</h3>\n<p>连续批处理的前提是 KV 可按块分配而非按请求整段预留。分页机制把 KV 切成固定大小的块，逻辑上连续的序列映射到物理上不连续的块，块表记录映射关系。视觉前缀在这里有一个特殊性质：同一张图、同一分辨率档位下，$N_v$ 是确定的，前缀内容在投影层输出后即固定，因此视觉 KV 块具备跨请求复用的可能——相同图像在多个请求中重复出现时，前缀块可以共享，只增引用计数而不重复写入。</p>\n<p>复用带来的收益是显存与预填算力双降：预填阶段不必重算视觉编码器前向与投影层，直接挂载已有块；显存上多个请求共享同一批物理块。代价是块表的引用管理复杂化，回收时机取决于最后一个引用释放，若请求生命周期差异大，共享块会被长请求钉住，形成“块泄漏”式的显存占用。伪代码思路如下：</p>\n<div class=\"formula\">$$\\text{alloc}(N_v, N_t):\\ \\text{blocks} \\leftarrow \\text{lookup}(\\text{img\\_hash}, \\text{res})\\ \\text{or}\\ \\text{encode+proj};\\ \\text{ref++};\\ \\text{append}(\\text{txt\\_blocks})$$</div>\n<p>分页还决定了碎片形态。批内视觉前缀长度方差大时，块分配器面对的是尺寸不一的请求，短请求释放的块未必能容纳长请求的前缀，产生外部碎片。工程上常用做法是按 $N_v$ 档位预分块池，把相近前缀长度的请求导向同一池，减少跨池搬迁。这个代价体现在调度器复杂度与块池命中率上，而非直接体现在延迟数字里，但命中率下降会转化为预填阶段的重复编码开销。</p>\n<p>另一个代价是预填与解码的资源竞争。视觉前缀的预填是一次性的大块写入，若与正在解码的批共享同一显存池，预填峰值会瞬时抬高水位，挤压解码批的可用块。分离式预填/解码的动机之一就在这里：把视觉编码与投影的算力峰值隔离到独立资源池，解码侧只做 KV 读取与追加，水位曲线更平滑。材料未给出并行拓扑与量化方案，因此块大小、池容量这些参数只能按 $N_v$ 线性关系定性设定。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-21\">二十一 · 压缩与卸载：在常驻项上做减法</h3>\n<p>视觉 KV 是常驻项，压缩它的收益最直接。可做的减法分三类：前缀长度压缩、数值精度压缩、位置卸载。前缀长度压缩是在投影层输出后合并或丢弃部分视觉 token，把 $N_v$ 降下来，$M_{\\mathrm{KV}}$ 随之线性下降；这条路径的代价是跨模态注意力可读的视觉证据变少，材料明确指出该范式未内置压缩或合并机制，高分辨率输入下需外部策略控制前缀长度，因此压缩比与对齐质量之间的权衡无法从材料中核验。</p>\n<p>数值精度压缩作用于视觉 KV 或投影层权重时，误差会传导到跨模态注意力输出。设视觉 KV 以 $b_v$ 字节存储、文本 KV 以 $b_t$ 字节存储，混合精度下的 KV 占用为：</p>\n<div class=\"formula\">$$M_{\\mathrm{KV}}^{\\mathrm{mix}} = 2 L H_{kv} d_h \\big( b_v N_v + b_t (N_t + N_{gen}) \\big)$$</div>\n<p>当 $N_v$ 远大于 $N_t$ 时，$b_v$ 的下降对总占用的边际贡献最大，这正是视觉 KV 单独降精度的动机。但视觉 token 承载的是连续视觉特征，量化误差在跨模态注意力里被放大后直接影响生成内容的视觉 grounding，材料未给出精度档位与误差数据，工程上只能以“先在小分辨率档位验证对齐、再逐档放开”的方式推进，不能直接套用文本 KV 的低精度经验。</p>\n<p>卸载是把冷视觉 KV 换出到主机内存或远端存储。判据是访问频度：解码阶段每层都要读全部视觉 KV，卸载会引入回读带宽开销，只有当单请求的视觉前缀极长、且批内并发低到回读延迟可被生成时间掩盖时才划算。代价体现在带宽上——视觉 KV 的回读量与 $N_v$ 成正比，若回读路径与解码读取路径争抢 HBM 带宽，解码吞吐会被拖低。一个具体例子：长视频或多图请求的视觉前缀远大于单图请求，若全部常驻，显存水位被少数长请求钉死；按块粒度把低频访问的远端视觉块换出，可以把水位压回可调度区间，但每次回读都是一次带宽支出，需在调度器里计入准入判断。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-22\">二十二 · 带宽瓶颈的位置：预填吃算力，解码吃带宽</h3>\n<p>视觉前缀把瓶颈位置改变了。纯文本解码是典型的带宽受限：每生成一个 token 要把权重与全部 KV 读一遍，算力利用率低。加入视觉前缀后，预填阶段变成算力受限：编码器前向是纯视觉算力、与文本长度无关，投影层映射与视觉 KV 写入是一次性大块操作，跨模态注意力在预填时要一次性处理全部视觉 token，首 token 延迟由这一段主导。也就是说，同一请求在不同阶段的瓶颈性质不同，优化手段不能互换。</p>\n<p>解码阶段的带宽账可以写成：每步读取量为权重字节加 KV 字节，其中 KV 读取量与 $N_v + N_t + N_{gen}$ 成正比。视觉 KV 常驻意味着每一步解码都要把这份常驻项读一遍，即便它不再变化。设 HBM 带宽为 $B$，单步解码时间下界为：</p>\n<div class=\"formula\">$$t_{\\mathrm{step}} \\gtrsim \\frac{W + 2 L H_{kv} d_h b (N_v + N_t + N_{gen})}{B}$$</div>\n<p>$W$ 为参与计算的权重字节。$N_v$ 越大，解码每步的 KV 读取量越大，单步时间下界越高，吞吐越低。这就是“视觉 token 拉长 KV cache 抬高跨模态注意力算力”的带宽侧表述：算力开销在预填，带宽开销在解码，两者都随 $N_v$ 线性增长，但落在不同的资源上。工程判断是：压缩 $N_v$ 同时缓解两侧，而降精度主要缓解解码侧的带宽压力，对预填算力的缓解有限。</p>\n<p>HBM3e 容量怎么算，只能按结构关系推。单卡可用容量减去权重常驻、减去激活峰值、减去框架与通信缓冲，剩余部分除以单请求 KV 字节数，得到可并发请求数的上界。由于材料未给出权重规模与精度档位，这个除法无法落具体数字，但可以给出可复算的预算模板：先固定 $L$、$H_{kv}$、$d_h$、$b$ 四个结构参数，再按分辨率档位枚举 $N_v$，按负载形态枚举 $N_t$ 与 $N_{gen}$，逐档算出 $M_{\\mathrm{KV}}$，最后用剩余容量除以最大档位的 $M_{\\mathrm{KV}}$ 得到最坏情况并发下界。这个模板的价值在于它把“分辨率档位”这个旋钮与“并发上界”直接连起来，容量规划时可以逐档核验，而不是拍一个总数。</p>\n<p>一个具体例子：若某档分辨率下 $N_v$ 是另一档的数倍，则同一剩余容量下可并发请求数按比例下降；批调度若仍按文本长度分桶，会把高 $N_v$ 请求与低 $N_v$ 请求混批，实际并发被最坏请求决定，容量利用率低于预算值。监控应覆盖视觉 token 数、预填耗时、KV 占用与批内长度方差四项，材料未给出阈值，但这四项是唯一能把预算与实际水位对上的观测面。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-23\">二十三 · 可复算的显存预算：从结构参数到准入判断</h3>\n<p>把前面的式子组装成一份可复算预算，步骤是确定的。第一步，列出结构参数 $L$、$H_{kv}$、$d_h$、$b$，这些由模型配置决定，材料未给出具体值，但部署时必须先从配置里读出。第二步，按预处理分辨率档位枚举 patch 网格，得到每档的 $N_v$；分辨率是容量规划的关键旋钮，档位表就是预算表的行。第三步，按负载形态给出 $N_t$ 与 $N_{gen}$ 的分布，材料未给出长度分布数字，工程上以观测到的分位数代入，取高分位做最坏情况预算。第四步，逐行算 $M_{\\mathrm{KV}}$，加上权重常驻与激活峰值，得到单请求总占用。第五步，用卡容量除以单请求总占用，得到该档位下的并发上界，再乘以一个由块碎片与共享块引用决定的有效系数。</p>\n<p>准入判断应直接引用这份预算，而不是引用平均占用。伪代码思路：请求到达时读出图像分辨率档位得到 $N_v$，读出文本长度得到 $N_t$，查预算表得到该组合的 $M_{\\mathrm{KV}}$，与当前可用块池比较，不足则排队或降档。降档是一个显式动作：把分辨率降一档，$N_v$ 下降，$M_{\\mathrm{KV}}$ 下降，请求得以准入，代价是视觉证据减少。这个动作把“显存约束”翻译成“服务质量档位”，是容量规划里最实用的一个接口。</p>\n<p>预算表还要覆盖共享块的情形。若相同图像在批内重复，视觉前缀块共享，实际占用低于逐请求相加的值，预算表应给出“独占”与“共享”两列，调度器按图像哈希命中率在两者之间插值。命中率高时并发上界显著抬升，命中率低时退回独占预算。这个插值系数无法从材料中取得，只能由服务侧观测填充，但它把复用机制与容量规划连成了一条可核验的链路。</p>\n<p>最后落在工程判断上：视觉 token 的显存代价是线性且常驻的，任何“平均一下”的预算都会在长前缀请求上失效；可复算的预算必须以分辨率档位为行、以高分位文本长度为列，逐格算出 $M_{\\mathrm{KV}}$，并把分页块池的有效系数与共享块命中率作为两个显式修正项写进表里。预算表一旦建立，压缩、降精度、卸载三种手段的收益都可以直接折算成表中的行变化，而不必依赖材料未给出的吞吐数字。</p>\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-24\">二十四 · 视觉前缀把批处理的不对称性放大</h3>\n<p>在纯文本服务里，连续批处理（continuous batching）之所以有效，是因为序列长度虽然参差，但每个 token 的计算代价同质。视觉指令微调范式打破了这一点：一条请求进入解码器时，前缀里已经躺着 <span>Proj(Enc(X_img))</span> 产生的一整段视觉 token，它们不参与自回归生成，却全程占据 KV cache 位置。批调度器面对的不再是“长度不一的文本”，而是“长度不一且不可压缩的视觉前缀 + 长度不一的文本”。</p>\n<p>这直接改变了准入判断的量纲。文本请求的批内代价近似正比于当前活跃 token 数；图文请求的代价在预填阶段有一个与生成长度无关的固定项，即视觉 token 数 <span>N_v</span> 乘以每层 KV 的单 token 字节数。若投影层输出维度为 <span>d</span>、层数为 <span>L</span>、精度为 <span>b</span> 字节，则单请求视觉 KV 的常驻量为：</p>\n<div class=\"formula\">$$M_{v}=2\\cdot L\\cdot N_{v}\\cdot d\\cdot b$$</div>\n<p>系数 2 来自 K 与 V 两份缓存。这个式子的工程含义是：<span>N_v</span> 由预处理分辨率与 patch 网格决定，分辨率档位一升，<span>M_v</span> 线性上升，而它与该请求还要生成多少 token 毫无关系。于是调度器必须把“视觉前缀占用”和“解码增量占用”分开记账，否则一个高分辨率短回答的请求会长期占着大块显存却产出极少 token，拖垮整批的有效吞吐。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-25\">二十五 · 连续批处理在视觉场景下的改造</h3>\n<p>标准连续批处理在每个解码步结束后回收已完成序列的槽位，把新请求插入。对图文混批，插入时机需要前移：新请求的视觉编码前向与投影层映射可以在 GPU 上异步执行，但它的视觉 KV 写入必须等预填完成才占位。合理的做法是把请求生命周期拆成三段——编码/投影、视觉预填、解码——调度器只对进入“视觉预填”的请求分配 KV 块，编码阶段用独立的显存池承载中间特征图，避免 patch 特征与 KV 争抢同一块高带宽显存。</p>\n<p>伪代码层面的准入逻辑可写成：对每个待入批请求估计 <span>cost = α·N_v + β·N_txt_prefill + γ·N_decode_expected</span>，其中 <span>α</span> 反映视觉预填的算力峰值、<span>β</span> 反映文本预填、<span>γ</span> 反映解码步的边际代价；只有当批内剩余 KV 块数与算力预算同时满足时才准入。这里的 <span>N_decode_expected</span> 是输出长度预估，材料未给出长度分布，因此工程上只能用保守上界或按历史分位数截断，宁可早回收也不让长尾请求无限占位。</p>\n<p>代价落在两个指标上：其一是首 token 延迟（TTFT），视觉预填一次性处理全部视觉 token，是算力峰值所在；其二是批的有效吞吐，因为视觉 KV 常驻导致同样显存能容纳的并发请求数下降。分辨率越高，这两个指标越同时恶化，而调度器无法通过“多批几次”来摊薄——视觉前缀是每请求一次性的固定成本。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-26\">二十六 · chunked prefill：把视觉预填切开的边界在哪</h3>\n<p>chunked prefill 的本意是把长预填切成若干块，与解码步交错执行，压平算力峰值、改善 TTFT 的方差。对图文请求，切分点的选择有硬约束：视觉 token 在投影层之后才成为 KV，编码器前向本身不可切（patch 网格是一次前向），可切的只有“视觉 token 写入 KV + 文本预填”这一段。因此 chunk 的粒度应至少覆盖一个完整的视觉前缀块，否则跨模态注意力在后续层读到不完整的视觉 KV，数值上不成立。</p>\n<p>设视觉 token 数为 <span>N_v</span>、chunk 大小为 <span>C</span>，则视觉预填被切成 <span>⌈N_v/C⌉</span> 个块，每块与若干解码步交错。块太小则调度开销与 KV 块分配碎片上升，块太大则失去压峰意义。工程判断是让 <span>C</span> 与解码批的 token 预算同量级，使每个调度周期内“预填算力 + 解码算力”大致均衡；这要求调度器知道当前批的解码 token 总数，而这在连续批处理里是动态的，因此 chunk 大小应作为随批状态调整的变量而非固定超参。</p>\n<p>代价体现在尾延迟上：chunked prefill 把一条请求的预填拉长到多个周期，单请求 TTFT 变长，但批内其他请求的解码步不再被长预填阻塞，尾延迟（P99）收敛。对图文混批，这个取舍尤其明显——一个高分辨率请求若整段预填，会让同批所有解码请求停等一个周期；切块后停等被摊薄，代价是该高分辨率请求自己晚几个周期出首 token。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-27\">二十七 · 优先级、抢占与视觉 KV 的回收代价</h3>\n<p>抢占（preemption）在文本服务里通常是重算或换出 KV 块。视觉场景下这两条路代价不对称：换出视觉 KV 到主机内存再换回，搬运量是 <span>M_v</span>，对高分辨率请求可达数十 MB 量级（材料未给具体数字，但量纲由 <span>N_v·d·L</span> 决定），PCIe 往返会直接击穿 TTFT 目标；重算则要重新跑编码器前向与投影层，纯视觉算力重复支付。因此调度策略应优先“不抢占视觉前缀已写入的请求”，把抢占压力转移到纯文本请求或尚未进入视觉预填的请求上。</p>\n<p>优先级设计要区分两类 SLO：交互式请求关心 TTFT，批式请求关心总吞吐。可行做法是给视觉前缀长度设阈值分桶，短前缀请求进高优先级队列、长前缀请求进低优先级队列但保证不被饿死；抢占只允许发生在解码阶段且仅换出文本 KV，视觉 KV 视为不可换出的常驻块。代价是显存利用率下降——常驻块无法被复用——但这换来的是尾延迟可控，因为最坏情况从“重跑编码器”降为“等一个解码周期”。</p>\n<p>一个具体例子：同批里一条 4K 视觉 token 的请求与十条短文本请求共存。若允许抢占视觉 KV，短文本请求的抖动会传导成视觉请求的编码器重跑，整批 P99 抬升；若禁止，短文本请求只能在剩余 KV 块里排队，但它们的解码步仍能连续推进，P99 由最长前缀请求的预填时间决定而非由抢占抖动决定。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-28\">二十八 · 分离式预填/解码对视觉链路的特殊约束</h3>\n<p>预填与解码分离部署（disaggregated prefill/decode）把算力峰值阶段与内存带宽敏感阶段放到不同节点，靠 KV 传输衔接。视觉链路在这里多了一段：编码器与投影层应归属预填侧，因为它们是纯视觉算力且输出即视觉 KV；解码侧只接收视觉 KV 与文本 KV，不再持有编码器权重。这样解码节点的显存全部用于 KV 池，容纳更多并发解码请求。</p>\n<p>传输量是设计核心：每条请求从预填侧传到解码侧的 KV 字节数为 <span>M_v + M_txt_prefill</span>，视觉部分往往是主导项。若互联带宽为 <span>B</span>，则传输时延下界为 <span>(M_v+M_txt)/B</span>，它与解码侧的首 token 等待直接相加。因此分离式架构对视觉请求的收益取决于 <span>M_v</span> 与互联带宽的比值：高分辨率、多图请求在小带宽链路上会因传输而抵消分离带来的算力收益。工程上应把视觉 KV 的传输与文本 KV 分开调度，允许解码侧在视觉 KV 到达前先做位置编码与注意力掩码准备，把传输时延藏在计算后面。</p>\n<p>代价还包括故障域扩大：预填侧编码器前向失败会连带整条请求重试，而视觉 KV 已写入的部分需要显式回收，否则 KV 池泄漏。监控应覆盖视觉 KV 传输字节数、预填侧队列深度与解码侧 KV 池水位，材料未给阈值，但三者的比值关系决定了分离式部署是否真的压低了尾延迟。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-29\">二十九 · 尾延迟的压法：把方差来源逐个钉住</h3>\n<p>图文混批的尾延迟有三个方差来源：视觉前缀长度方差、预填算力峰值、以及抢占引发的重算。压尾延迟不是调一个参数，而是分别处理：对前缀长度方差，用分桶把 <span>N_v</span> 相近的请求放同批，桶内 KV 占用可预测，桶间不混批；对预填峰值，用 chunked prefill 把视觉预填切块并与解码交错；对抢占重算，用“视觉 KV 不可换出”策略把最坏路径从重跑编码器降为等待。</p>\n<p>三者叠加后的调度目标是让批内 <span>max(M_v)</span> 与批内总算力预算匹配，而不是让平均占用匹配。因为尾延迟由最坏请求决定，按均值装箱必然在长前缀请求上失守。一个可操作的判据是：准入时检查“当前批最大视觉前缀 + 新请求视觉前缀”是否超过 KV 池的单批上限，超过则新请求进下一批而非硬塞。代价是短请求可能被长请求挡在门外，因此需要独立的短前缀快车道来保住交互式 SLO。</p>\n<p>最终落在工程判断上：视觉指令微调范式的推理调度，本质是把视觉 token 当作不可压缩的常驻前缀来记账，连续批处理负责吞吐、chunked prefill 负责压峰、优先级与抢占策略负责隔离最坏路径、分离式部署负责把算力峰值与显存压力解耦。四者共同的约束是 <span>M_v</span> 随分辨率线性增长且不随生成长度衰减——任何调度策略都无法绕过这条线性关系，只能决定由谁来承担它。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-30\">三十 · 视觉前缀分桶与抢占：连续批处理在多模态负载下的失效边界</h3>\n\n<p>把视觉 token 当作普通文本 token 塞进连续批处理（continuous batching）的迭代调度器，会在两个地方失效。其一是预填阶段的算力峰值：文本请求的预填代价大致随 prompt 长度线性增长，而视觉请求的预填是一次性把全部视觉 token 过一遍跨模态注意力，其峰值由 <span class=\"formula\">$$T_{\\text{prefill}} \\approx \\max\\big(\\tau_{\\text{enc}} + \\tau_{\\text{proj}},\\; \\alpha \\cdot N_v \\cdot d\\big)$$</span> 刻画，其中 <span class=\"formula\">$$N_v$$</span> 为视觉 token 数、<span class=\"formula\">$$d$$</span> 为投影输出维度、<span class=\"formula\">$$\\alpha$$</span> 为每 token 每层的注意力代价系数。调度器若按 token 数而非按视觉前缀长度计费，就会把高分辨率请求与短文本请求混进同一迭代步，使该步的预填耗时被最长的视觉前缀拉长，整批的首 token 延迟一起被拖高——这是尾延迟而非均值延迟的恶化，SLO 上表现为 p99 超标而 p50 几乎不动。</p>\n\n<p>其二是显存碎片。视觉 KV 在请求生命周期内常驻且不可回收，单请求占用为 <span class=\"formula\">$$M_v = N_v \\cdot d \\cdot L \\cdot b$$</span>，<span class=\"formula\">$$L$$</span> 为层数、<span class=\"formula\">$$b$$</span> 为每元素字节数。分页 KV 管理器按块分配，块大小固定，视觉前缀长度离散（分辨率档位决定 patch 网格）导致每请求尾部浪费一个不完整块；批内长度方差越大，碎片率越高，可容纳的并发请求数下降。工程上的做法是按视觉 token 数分桶准入：桶内长度接近，块浪费可控，桶间不混批；代价是短请求可能等待同桶请求凑批，牺牲一部分吞吐换尾延迟稳定。分桶粒度是显式旋钮，粗桶吞吐高但尾延迟差，细桶反之。</p>\n\n<p>chunked prefill 对视觉前缀的适用性有明确边界。文本侧把长 prompt 切块是为了让解码步插入预填块之间、压低 ITL；但视觉 token 在跨模态注意力里被所有后续解码步读取，切块只是把一次性预填摊到多个迭代步，KV 写入总量不变，显存峰值不变。真正受益的是那些视觉编码前向与预填重叠的流水线：编码器前向是纯视觉算力、与文本长度无关，可与上一批的解码步并行，此时 chunked prefill 的作用是把预填块塞进解码步的空隙而非降低总代价。若编码器前向本身已是瓶颈，切块无收益，只是增加了调度开销。</p>\n\n<p>优先级与抢占在多模态场景下要区分可抢占与不可抢占资源。解码中的文本 KV 可被换出重算，代价是重算 token 的算力；视觉 KV 换出意味着重新跑编码器与投影层，代价远高于文本，且编码器前向不受批内其他请求影响，重算无法摊薄。因此抢占策略应优先驱逐文本侧 KV、保留视觉前缀，或直接拒绝新到的视觉请求而非抢占在途请求。分离式预填/解码在这里的收益来自资源异构：预填节点承担编码器前向与视觉 KV 写入，解码节点只做自回归读取，视觉 KV 需跨节点传输，带宽成为新的约束项——传输量与 <span class=\"formula\">$$M_v$$</span> 同阶，NVLink 域内可承受，跨域则可能抵消分离带来的收益。判断标准是传输时间是否小于被卸载的预填时间，否则分离只是把瓶颈从算力搬到链路。</p>\n\n<table class=\"mini\"><thead><tr><th>调度策略</th><th>失效条件</th><th>系统代价</th></tr></thead><tbody><tr><td>不分桶混批</td><td>批内视觉前缀方差大</td><td>尾延迟恶化、显存碎片上升</td></tr><tr><td>chunked prefill</td><td>编码器前向为瓶颈</td><td>调度开销增加、KV 峰值不变</td></tr><tr><td>抢占视觉 KV</td><td>在途请求被驱逐</td><td>重跑编码器、算力浪费</td></tr><tr><td>分离式预填/解码</td><td>跨域带宽不足</td><td>视觉 KV 传输抵消收益</td></tr></tbody></table>\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-31\">三十一 · 视觉前缀把并行切分的账本改写</h3>\n<p>视觉指令微调的推理链路里，序列被分成两段性质不同的前缀：视觉 token 由编码器与投影层一次性生成、写入 KV cache 后在整个解码生命周期内不变；文本 token 则逐位追加。这个“一段静态、一段动态”的结构直接决定了并行切分的选择。纯文本 LLM 的 TP 切分可以假定所有层、所有 token 的激活与 KV 形状一致，按隐藏维均分即可；而多模态请求的视觉 KV 在预填阶段一次性写满，其单 token 显存增量由投影层输出维度 <em>d</em><sub>v</sub> 决定，若 <em>d</em><sub>v</sub> 与语言模型隐藏维 <em>d</em><sub>m</sub> 不等，KV 头数与层数的切分就必须按实际投影后的形状重算，而不是照抄文本模型的 TP 度数。</p>\n<p>更关键的是，视觉 KV 常驻显存意味着 TP 组内每张卡都要为同一批视觉前缀保留等量 KV 分片。设单请求视觉 token 数为 <em>N</em><sub>v</sub>，层数 <em>L</em>，KV 头数 <em>H</em><sub>kv</sub>，头维 <em>d</em><sub>h</sub>，每元素字节数 <em>b</em>，则单请求视觉 KV 的显存下界为：</p>\n<div class=\"formula\">$$M_{\\mathrm{vkv}} = 2 \\cdot L \\cdot N_{v} \\cdot H_{kv} \\cdot d_{h} \\cdot b \\Big/ \\mathrm{TP}$$</div>\n<p>TP 增大能摊薄这个下界，但摊薄的是每卡容量，不是总容量；总容量随 <em>N</em><sub>v</sub> 线性上升，分辨率档位一调高，整组卡的显存预算同步吃紧。工程上的直接后果是：TP 度数不能只按模型权重放下与否来选，还要按“目标分辨率下最坏视觉前缀长度 × 并发批大小”反推。举例来说，一个服务若把预处理分辨率固定在高档，单图视觉 token 数远大于文本指令长度，则 TP=8 的收益主要体现在权重与 KV 分片上，而跨模态注意力的算力峰值仍集中在预填阶段的那一次前向，TP 并不能把这一次前向的时延按度数线性缩短——集合通信在每一层注意力后都要插入，层数越多，同步点越密。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-32\">三十二 · TP 与 EP：集合通信的两种代价曲线</h3>\n<p>TP 在解码器每层内部切分注意力和 MLP，代价是每层两次 All-Reduce（注意力输出一次、MLP 下投影一次），通信量与激活大小成正比、与批内 token 数成正比。预填阶段 token 多，All-Reduce 的数据量大但可摊到大量计算上，通信/计算比尚可；解码阶段每步只产生一个 token（或投机解码下少量 token），All-Reduce 的数据量骤降，但每步都要同步一次，延迟被固定成“层数 × 同步开销”，这是解码 TP 的典型瓶颈形态。视觉前缀不改变这个结构，却把预填阶段的激活规模抬高：视觉 token 与文本 token 拼成统一序列后，预填的序列长度由 <em>N</em><sub>v</sub> + <em>N</em><sub>txt</sub> 决定，跨模态注意力在每层都要对这整段做 QK<sup>T</sup>，TP 组内的 All-Reduce 也随之变大。</p>\n<p>EP 则把 MoE 专家分散到不同卡上，每层注意力的 All-Reduce 换成两次 All-to-All：一次把 token 按路由分发到专家所在卡，一次把专家输出收回。All-to-All 的通信量取决于被路由 token 数与隐藏维，且是点对点模式，对拓扑敏感——在 NVLink 域内可以走全互联，跨域则要经 InfiniBand 或其它 fabric，带宽骤降。多模态请求在这里有个不对称：视觉 token 的路由分布与文本 token 不同，视觉特征经投影层后落在词嵌入空间的某些区域，若路由对这些位置有偏，All-to-All 的负载会在专家间倾斜，个别卡成为热点，整层等待最慢的那张卡。工程判断是：EP 适合专家数远大于 TP 度数、且路由相对均衡的配置；一旦视觉前缀使路由倾斜，就要么加辅助负载均衡损失（训练侧的事，本卷不展开），要么在推理侧对视觉 token 单独做容量因子放宽，用更多冗余专家吸收倾斜。</p>\n<table class=\"mini\"><thead><tr><th>切分方式</th><th>每层通信原语</th><th>通信量随什么增长</th><th>多模态下的敏感点</th></tr></thead><tbody><tr><td>TP</td><td>All-Reduce ×2</td><td>批内 token 数 × 隐藏维</td><td>预填序列被视觉 token 拉长</td></tr><tr><td>EP</td><td>All-to-All ×2</td><td>被路由 token 数 × 隐藏维</td><td>视觉 token 路由倾斜造成热点</td></tr><tr><td>PP</td><td>点对点激活传递</td><td>微批大小 × 隐藏维</td><td>视觉预填集中在首段，段间气泡</td></tr><tr><td>DP</td><td>梯度/参数同步（推理侧仅副本）</td><td>副本间无每层通信</td><td>副本间视觉前缀长度方差导致负载不均</td></tr></tbody></table>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-33\">三十三 · PP 与 DP：气泡与副本的不均衡</h3>\n<p>PP 把层切成若干段放在不同卡上，段间只传激活，通信量小但引入流水气泡。多模态推理对 PP 的特殊压力在于预填阶段的极端不均衡：视觉编码器前向与投影层发生在最前段，视觉 token 一次性涌入，首段成为算力峰值段，后续段在等激活；解码阶段每步只过一个 token，气泡占比反而下降。于是 PP 的段划分若按解码稳态的算力均衡来切，预填阶段就会出现首段堵、尾段闲的形态，首 token 延迟被首段主导。可行的做法是把视觉编码与投影层单独放在一段（甚至单独一组卡），与语言解码段解耦，让视觉前向与文本预填可以重叠——这正是分离式预填/解码在 PP 维度上的投影。</p>\n<p>DP 在推理侧表现为多副本并行：每个副本持有完整权重、独立处理请求，副本之间不做每层通信，只在入口做请求分发。它看似与通信无关，实则把瓶颈转移到负载均衡上。批内视觉前缀长度方差大，若分发器按请求数轮询而不看视觉 token 数，某些副本会连续接到高分辨率长前缀请求，KV 占用飙升、尾延迟恶化，而另一些副本空闲。分桶调度的粒度必须细到“视觉 token 数区间 × 文本长度区间”，并且分发器要能读到预处理后的实际 token 数，而不是请求到达时的图像元数据——分辨率归一与分块在预处理阶段才定下 patch 网格，早于编码器前向但晚于请求接入，分发决策点必须卡在这个位置之后。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-34\">三十四 · NVLink 5 与 NVSwitch：域内带宽把瓶颈推到哪里</h3>\n<p>Blackwell 世代的 NVL72 机柜把 GPU 通过 NVLink 5 与 NVSwitch 组成全互联域，域内任意两卡之间可走单跳高带宽链路，All-Reduce 与 All-to-All 在域内的有效带宽远高于跨域 fabric。这改变了瓶颈的位置：TP 的每层 All-Reduce 在域内不再是主要成本，解码阶段的同步开销被压到可接受范围，TP 度数可以开得更大而不至于被通信拖死；EP 的 All-to-All 在域内也接近全互联语义，路由倾斜的代价从“带宽不够”退化为“热点卡排队”。真正被推到台前的是跨域链路——当 TP 或 EP 组跨越多个 NVL72 机柜，集合通信要经 fabric 转发，带宽与延迟都上一个台阶，此时通信才成为显性瓶颈。</p>\n<p>判断通信是否成为瓶颈，可以用一个粗粒度的比值：单层计算时间与单层集合通信时间之比。设单层浮点算力为 <em>F</em>、单层有效 FLOPs 为 <em>C</em>，集合通信量为 <em>B</em> 字节、有效带宽为 <em>W</em>，则</p>\n<div class=\"formula\">$$\\mathrm{ratio} = \\frac{C/F}{B/W}$$</div>\n<p>比值大于 1 时计算主导，通信可被隐藏；小于 1 时通信主导，加卡不增吞吐。多模态预填阶段 <em>C</em> 因视觉 token 拉长序列而变大，比值偏向计算主导，通信尚可隐藏；解码阶段 <em>C</em> 极小，比值迅速跌到 1 以下，此时 TP 的每步 All-Reduce 就是硬成本。这解释了为什么解码侧更倾向用更大的批来摊薄同步开销——批内请求数上升使每步 All-Reduce 的数据量上升，但同步次数不变，单位 token 的通信成本被摊薄。视觉前缀常驻 KV 又限制了批大小上限，两者构成一对拉扯：批越大越能摊薄通信，但每请求的视觉 KV 占位使批的显存预算更早耗尽。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-35\">三十五 · NIXL 传输与 KV 的跨节点搬运</h3>\n<p>分离式预填/解码把预填与解码拆到不同节点池，视觉 token 的 KV 需要在预填完成后从预填节点传到解码节点。NIXL 这类传输层的作用是把 KV 块的搬运从“经主机内存中转”变成“GPU 到 GPU 的直接读写”，减少拷贝次数与 CPU 介入。对多模态请求，这笔搬运的规模由视觉 KV 决定：<em>N</em><sub>v</sub> 个 token × <em>L</em> 层 × KV 头维度 × 字节数，视觉前缀越长，跨节点传输量越大，传输时间可能吃掉预填与解码解耦带来的重叠收益。工程上要按视觉 token 数决定“哪些请求值得走分离式路径”：短前缀请求留在同节点完成预填与解码，长前缀请求才值得把 KV 搬出去，否则传输开销超过解耦收益。</p>\n<p>传输层的另一个代价是显存注册与固定缓冲。GPU 直接传输要求源与目的缓冲区被注册为可被传输引擎访问，注册本身占时间与显存；若每个请求动态分配 KV 块再注册，开销会累积。可行做法是按视觉 token 数分档预分配固定大小的 KV 缓冲池，请求按档位取块，传输时整块搬运，避免逐请求注册。这与前文的批调度分桶是同一套粒度：分桶既服务调度，也服务传输。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-36\">三十六 · 通信瓶颈的判定与工程取舍</h3>\n<p>把上述几条收敛成一个判定流程：先看并行组是否落在单个 NVLink 域内，域内则 TP/EP 的集合通信通常可被计算隐藏，瓶颈更可能在显存容量与批调度；跨域则先算集合通信量与有效带宽的比值，比值低于 1 就不要再加卡，转而缩并行度、加副本走 DP。再看阶段：预填阶段序列被视觉 token 拉长，计算主导，通信可隐藏；解码阶段每步同步固定，通信主导，应靠增大批与投机解码摊薄。最后看请求构成：视觉前缀长度方差大时，DP 副本间的负载不均与 EP 的路由倾斜会先于带宽成为瓶颈，此时优化分发与分桶的收益高于调并行度。</p>\n<p>一个具体的取舍例子：同一套服务要同时承接低分辨率短指令与高分辨率长指令两类请求。若统一用大 TP 度数，低分辨率请求的解码阶段被每步 All-Reduce 拖慢，高分辨率请求的预填阶段又因 TP 组内激活切分而增加跨卡同步；若改为按视觉 token 数分池——短前缀池用小 TP、大批、同节点预填解码，长前缀池用大 TP、分离式预填、NIXL 搬 KV——两类请求各走各的通信曲线，尾延迟与吞吐的折中才成立。代价是池间资源不能弹性互借，容量规划要按两池的峰值分别留量，这是用显存冗余换通信效率的典型工程判断。</p>\n<p>最终落在一条可执行的监控口径上：按请求记录视觉 token 数、预填耗时、每层集合通信耗时占比、KV 传输字节数与批内视觉前缀长度方差。通信是否成为瓶颈不靠猜，靠“集合通信耗时 / 单层总耗时”这个逐层比值——它超过阈值且随 TP 度数上升不降，就是该缩并行度或改拓扑的信号；它在预填阶段低、解码阶段高，就是该加大批或上投机解码的信号。视觉 token 作为常驻前缀把这两个信号同时放大，使多模态服务的并行拓扑选择比纯文本服务更早触到通信墙。</p>\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-37\">三十七 · 精度塌陷：从视觉 KV 到跨模态注意力的误差传导链</h3>\n<p>视觉指令微调范式把图像变成一段可消费的序列前缀，这决定了精度问题的发生位置与纯文本推理不同。误差不是从词嵌入开始，而是从投影层输出开始：<span class=\"formula\">$$\\mathbf{H}_{v}=\\mathrm{Proj}\\big(\\mathrm{Enc}(\\mathbf{X}_{\\mathrm{img}})\\big)$$</span> 一旦 <span class=\"formula\">$\\mathrm{Proj}$</span> 的权重或 <span class=\"formula\">$\\mathbf{H}_{v}$</span> 被量化，误差就随视觉 KV 常驻显存，并在解码器每一层被跨模态注意力反复读取。诊断上要把“精度塌陷”拆成三段独立观测：编码器输出特征分布、投影层输出与词嵌入空间的余弦对齐度、跨模态注意力输出与全精度基线的相对偏差。工程上最容易被忽略的是第二段——投影层是唯一把视觉空间映射到语言空间的算子，它的输出维度决定单视觉 token 的 KV 显存增量，量化这里等于同时改动了数值精度和前缀的几何结构。定位手法：固定同一批图文请求，分别跑全精度与目标精度，逐层记录跨模态注意力 logits 的 KL 散度；若散度在浅层就跳变，问题在投影层或视觉 KV 量化，若散度随层数累积放大，问题在低精度累加与 softmax 数值范围。代价上，精度塌陷不会表现为 OOM 或超时，而是表现为答案“看起来通顺但答非所问”的静默降级，监控必须把图文对齐类请求单列一条精度探针，而不是混在整体准确率里。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-38\">三十八 · OOM 的三种来源与显存账本</h3>\n<p>多模态服务的 OOM 很少是单一原因。第一类是视觉前缀膨胀：预处理分辨率上升直接线性抬高视觉 token 数，而视觉 KV 全程占位、解码阶段不释放，等于每个在途请求都背着一块只读显存。第二类是批内长度方差：按总 token 数准入会把一条高分辨率请求和若干短文本请求塞进同一批，短请求很快解码完却因整批同步而无法释放自己的 KV 块，形成显存碎片。第三类是投影层与视觉编码器的激活峰值：预填阶段一次性处理全部视觉 token，激活占用与视觉 token 数同阶，这部分峰值常被误算进稳态 KV 预算。显存账本应写成 <span class=\"formula\">$$M_{\\text{req}} \\approx n_{v}\\cdot d\\cdot L\\cdot b_{kv} + n_{t}\\cdot d\\cdot L\\cdot b_{kv} + M_{\\text{act}}(n_{v})$$</span> 其中 <span class=\"formula\">$n_v$</span> 为视觉 token 数、<span class=\"formula\">$d$</span> 为投影层输出维度、<span class=\"formula\">$L$</span> 为层数、<span class=\"formula\">$b_{kv}$</span> 为每元素字节数。诊断顺序：先看准入时是否只按文本长度估算，再看 KV 块分配器是否按视觉 token 数分桶，最后看预填激活峰值是否被计入并发上限。回滚手段是把分辨率档位与并发上限做成联动配置，而不是各自独立调参——降分辨率等于同时降 <span class=\"formula\">$n_v$</span> 和 <span class=\"formula\">$M_{\\text{act}}$</span>，是最快见效的显存回收动作。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-39\">三十九 · 批抖动与尾延迟：方差才是敌人</h3>\n<p>连续批处理在纯文本场景靠 token 预算就能稳定，多模态场景的扰动源是视觉前缀长度的双峰分布：低分辨率缩略图与高分辨率文档扫描混在同一流量里，批内 <span class=\"formula\">$n_v$</span> 的方差远大于文本长度方差。批抖动的表现是吞吐曲线随流量成分漂移——同一 QPS 下，图像占比升高时吞吐下降、首 token 延迟抬升，因为预填阶段被最长的视觉前缀拖住。定位方法：把每批的 <span class=\"formula\">$\\max(n_v)$</span>、<span class=\"formula\">$\\mathrm{var}(n_v)$</span> 与批完成时间一起打点，若批完成时间与 <span class=\"formula\">$\\max(n_v)$</span> 强相关而与平均 <span class=\"formula\">$n_v$</span> 弱相关，说明调度被长前缀绑架。对策是按视觉 token 数分桶准入，桶内再按文本长度排序，并给每桶独立的并发上限；桶边界要按分辨率档位而非连续值划分，避免桶过多导致批填充率下降。尾延迟的另一个来源是解码阶段的 KV 读取带宽：视觉 KV 常驻但每步都被读取，长前缀请求的解码步时间随 <span class=\"formula\">$n_v$</span> 上升，P99 会被少数高分辨率请求主导。监控上应把首 token 延迟与每 token 解码延迟分开统计，前者看预填，后者看带宽。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-40\">四十 · 静默降级：没有报错的失败</h3>\n<p>最危险的失败模式不产生异常。视觉 token 被截断、分辨率档位被静默下调、量化档位在负载高时自动切换，都会让服务“正常返回”但图文对齐质量下降。这类降级的共同特征是：请求成功率不变、延迟甚至变好、只有答案质量在漂。诊断需要三条独立探针。第一条是前缀完整性探针：记录每条请求实际写入 KV 的视觉 token 数并与预处理网格推算值比对，差值非零即说明发生了截断或合并。第二条是分辨率指纹：把预处理分辨率档位作为标签写入请求元数据，按档位分组统计答案长度与拒答率，档位间出现系统性偏移即为降级信号。第三条是跨模态注意力熵：在固定探针集上采样若干层的注意力分布熵，熵值骤降往往对应视觉 KV 被过度压缩或量化误差累积。回滚策略要区分“配置回滚”与“流量回滚”：前者把分辨率档位与量化档位恢复到上一稳定组合并冻结自动切换，后者把高分辨率请求引流到独立池，避免降级扩散到全量流量。静默降级的根因多半是容量规划把视觉 token 当成了可忽略的常数，回滚时必须同时修正准入公式里的 <span class=\"formula\">$n_v$</span> 项。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-41\">四十一 · 监控面与定位路径</h3>\n<p>监控指标要围绕视觉前缀这条主线组织，而不是复用文本服务的指标体系。四个必测面：视觉 token 数分布（按分辨率档位分桶的 P50/P99）、预填阶段耗时（与 <span class=\"formula\">$n_v$</span> 做相关性分析）、KV 占用中视觉部分占比（区分常驻与可回收）、批内 <span class=\"formula\">$n_v$</span> 方差。定位路径可以固定为一条决策链：首 token 延迟超标 → 查预填耗时与 <span class=\"formula\">$n_v$</span> 的相关性 → 相关则查分辨率档位分布是否漂移，不相关则查批内方差与调度分桶；吞吐下降 → 查批完成时间是否被 <span class=\"formula\">$\\max(n_v)$</span> 主导 → 是则收紧分桶，否则查解码带宽；OOM → 查准入公式是否漏算视觉 KV 与预填激活。回滚的最小单元应是“分辨率档位 × 量化档位 × 并发上限”三元组，任一维度变更都要留可回退的快照，因为这三者共同决定 <span class=\"formula\">$n_v$</span>、<span class=\"formula\">$b_{kv}$</span> 与在途请求数，单独回滚一项往往不能恢复稳态。表格给出各失败模式的观测面与首选动作：</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>首要观测</th><th>定位判据</th><th>回滚动作</th></tr></thead><tbody><tr><td>精度塌陷</td><td>跨模态注意力 KL 散度</td><td>浅层跳变指向投影层/视觉 KV 量化</td><td>恢复量化档位快照</td></tr><tr><td>OOM</td><td>视觉 KV 占比与预填激活峰值</td><td>准入漏算 <span class=\"formula\">$n_v$</span> 或激活未计入</td><td>降分辨率档位并联动并发上限</td></tr><tr><td>批抖动</td><td>批完成时间 vs <span class=\"formula\">$\\max(n_v)$</span></td><td>强相关即调度被长前缀绑架</td><td>收紧分桶边界与桶内并发</td></tr><tr><td>尾延迟</td><td>每 token 解码延迟 vs <span class=\"formula\">$n_v$</span></td><td>长前缀请求主导 P99</td><td>高分辨率请求引流独立池</td></tr><tr><td>静默降级</td><td>前缀完整性、分辨率指纹、注意力熵</td><td>成功率不变而质量分组偏移</td><td>冻结自动切换并恢复三元组快照</td></tr></tbody></table>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-42\">四十二 · 工程判断：把失败模式写进准入与配置</h3>\n<p>这套链路的失败模式有一个共同根源：视觉 token 是常驻前缀，它的数量在请求进入时就固定，之后既不能像文本 KV 那样随解码增长，也不能在批内被部分回收。因此诊断与回滚的重心不在解码器内部，而在准入与配置层。准入公式必须显式包含 <span class=\"formula\">$n_v$</span> 与预填激活项，分桶必须按分辨率档位离散化，量化档位必须与分辨率档位绑定成不可独立漂移的组合。监控上，把“视觉 token 数 × 分辨率档位 × 量化档位”作为请求的三元标签贯穿日志与指标，任何一项缺失都会让静默降级无法归因。回滚的设计原则是快照化而非逐项调参：一次变更同时改动三元组中的两项时，必须保留变更前的完整组合，否则恢复时无法判断是哪一项导致了精度或延迟偏移。最后一条判断标准很直接——如果一条请求的视觉 token 数在监控里不可见，那么它的所有失败模式都只能靠用户投诉来发现，这在工程上等同于没有监控。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-43\">四十三 · 视觉前缀的失效边界与可观测回滚</h3>\n<p>这套视觉 token 前缀方案最容易被误判的地方，是把视觉 KV 当成“另一种文本 KV”来管。文本 KV 随解码逐 token 增长，而视觉 KV 在预填阶段一次性写满、之后全程常驻，于是容量规划必须按“最坏单请求前缀”而不是按平均序列长度来做。设单请求视觉 token 数为 <span class=\"inline-math\">N<sub>v</sub></span>、每层每 token 的 KV 字节为 <span class=\"inline-math\">b</span>、层数为 <span class=\"inline-math\">L</span>，则视觉 KV 的常驻增量近似为</p>\n<div class=\"formula\">$$M_{\\mathrm{vkv}} \\approx 2 \\cdot N_{v} \\cdot b \\cdot L \\cdot n_{\\mathrm{req}}$$</div>\n<p>其中系数 2 对应 K/V 两份。分辨率档位一升，<span class=\"inline-math\">N<sub>v</sub></span> 随 patch 网格线性膨胀，<span class=\"inline-math\">M<sub>vkv</sub></span> 与跨模态注意力算力同步上升，而投影层输出维度只决定单 token 增量、压不住总量。这就是精度塌陷之外的第一个硬边界：OOM 往往不是解码阶段爆的，而是准入时按文本长度估算、预填时被视觉前缀一次性击穿。</p>\n<p>第二个失效条件是批抖动与尾延迟的耦合。批内各请求的视觉前缀长度方差大时，调度器若按到达顺序混批，短文本长图与长文本短图会被绑在同一批里，预填阶段被迫按最长前缀对齐，显存块按峰值预留却只被少数请求用满，形成碎片；解码阶段这些常驻前缀又持续占位，新请求进不来，尾延迟被拖长。工程上的对策是按 <span class=\"inline-math\">N<sub>v</sub></span> 分桶并给每桶独立的并发上限，代价是桶间负载不均时 GPU 利用率下降——这是用吞吐换尾延迟的显式交易，不是免费的。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>最可能机制</th><th>定位手段</th><th>回滚动作</th></tr></thead><tbody><tr><td>首 token 延迟突增</td><td>预填一次性处理全部视觉 token，算力峰值被低估</td><td>按桶记录预填耗时与 <span class=\"inline-math\">N<sub>v</sub></span> 分布</td><td>降分辨率档位或限制单批视觉 token 总量</td></tr><tr><td>显存缓慢爬升后 OOM</td><td>视觉 KV 常驻未随请求生命周期回收</td><td>跟踪 KV 块分配/回收比与常驻前缀数</td><td>收紧准入、缩短请求超时、强制回收空闲块</td></tr><tr><td>输出语义漂移但无报错</td><td>视觉 KV 或投影层低精度量化误差传导至跨模态注意力</td><td>同请求高低精度对照、固定种子重放</td><td>视觉 KV 回退高精度，仅文本侧保留量化</td></tr></tbody></table>\n<p>第三类是静默降级，最危险也最难监控。量化若作用于视觉 KV 或投影层权重，误差不会抛异常，只会让跨模态注意力输出偏移，表现为回答“看着像对的但细节错”。材料未给出精度档位与误差数据，因此不能假设低精度安全，只能把“同请求双精度对照重放”做成常驻探针，用固定图文样本集比对输出分布偏移，超阈值即触发回滚。监控面至少要覆盖四项：视觉 token 数分布、预填耗时、KV 常驻占用与批内长度方差；缺任何一项，OOM 与尾延迟都会以“偶发”形式出现而无法归因。回滚顺序应是先降分辨率与收紧分桶，再动量化档位——因为前者是可逆的容量旋钮，后者一旦影响对齐质量，重放对照的成本远高于降档。</p>\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-44\">四十四 · 口径先行：这份材料能登记什么、不能登记什么</h3>\n<p>读这篇论文的性能段落，第一件事不是找数字，而是确认数字的存在性。材料明确：未给出数据集名称与规模、未给出对照基线、未给出任何吞吐/延迟/显存/精度数值、未给出消融设置、未给出部署硬件档位、未给出并行拓扑与量化档位。这意味着任何“视觉 token 压缩比”“跨模态注意力开销降低多少”“量化误差多大”的陈述都无法从本文核验。工程读者必须把这篇论文当作<strong>机制登记卡</strong>而非<strong>性能基准卡</strong>：它确立的是视觉 token 作为序列前缀进入统一自回归解码这一接口事实，以及由此派生的代价结构，而不是可横向比较的指标。</p>\n<p>因此本部分的口径原则是：凡涉及数值，只允许两种写法——(a) 由材料给定的线性关系推出的定性趋势，例如“视觉 token 数随分辨率上升而线性抬高 KV 占用”；(b) 由公式结构决定的量纲关系，例如单 token 视觉 KV 显存增量由投影层输出维度决定。凡超出这两类的数字，一律标记为“材料未给出”，不得以行业惯例填补。这不是保守，而是防止把不可比的提升误读为可比。</p>\n<p>一个具体例子：若某后续工作报告“视觉 token 从 N 降到 N/4、首 token 延迟下降”，读者必须追问三件事——基线是否同一分辨率档位、是否同一 batch 与并发、TTFT 是否在同一预填口径下测得。本文没有提供这三项的锚点，所以该报告只能作为独立实验看待，不能挂在本文名下作为“本文方法的提升”。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-45\">四十五 · 硬件档位与 batch/并发：为什么本文无法绑定 Blackwell 配置</h3>\n<p>材料写明“部署硬件档位材料未给出，无法绑定 B200/B300/GB200 NVL72 具体配置”。这不是遗漏，而是范式论文的常态：它定义的是模型侧接口，硬件侧留白。对工程读者的直接后果是，本文的任何代价讨论都只能停在<strong>相对量</strong>层面——视觉前缀变长则 KV 占用变大、预填算力变大——而不能落到 SM100 的 TMEM 容量、2-SM MMA 的配对约束、NVLink 5 的域内带宽这些具体档位上。若要把本文机制移植到 Blackwell，硬件档位必须由部署方另行标定，本文不提供换算系数。</p>\n<p>batch 与并发同理：材料只给出“需按视觉 token 数分桶调度”“批内视觉前缀长度方差影响尾延迟”，未给出并发上限、batch 上限、SLO 目标。可用的推理只有一条结构性的：设批内第 i 个请求的视觉 token 数为 <span>v_i</span>、文本长度为 <span>t_i</span>，则该请求的 KV 位置数为 <span>v_i + t_i</span>，单批 KV 占用上界近似为</p>\n<div class=\"formula\">$$M_{\\text{batch}} \\approx \\sum_{i=1}^{B} s_{\\text{kv}} \\cdot (v_i + t_i) \\cdot L$$</div>\n<p>其中 <span>s_kv</span> 为单 token 单层 KV 字节数（由投影层输出维度与精度档位决定）、<span>L</span> 为解码器层数。该式说明：即使 <span>B</span> 固定，只要 <span>v_i</span> 方差大，<span>M_batch</span> 的上界就被最长前缀请求拉高，短请求被迫按长请求的块粒度占位，形成显存碎片。这正是材料所说“长短请求混批造成显存碎片与尾延迟恶化”的量化来源。分桶的本质是把 <span>v_i</span> 相近的请求放进同一批，使 <span>M_batch</span> 的求和项方差收窄，从而提高显存利用率而非提高单请求速度。</p>\n<p>代价落点：分桶提高显存利用率与吞吐，但会降低批内请求的多样性，短请求可能等待同桶请求凑批，抬高空闲等待；不分桶则尾延迟恶化。这是一个吞吐—尾延迟的显式权衡，本文未给出最优点，只给出机制。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-46\">四十六 · 指标定义：TTFT/TPOT/吞吐/显存/功耗各自被什么主导</h3>\n<p>材料给出了一条明确的归因：“首 token 延迟主要由视觉编码前向与预填阶段决定”“预填阶段需一次性处理全部视觉 token”。据此可以把 TTFT 拆成三段可加项：</p>\n<div class=\"formula\">$$\\mathrm{TTFT} \\approx T_{\\text{preproc}} + T_{\\text{enc}}(v) + T_{\\text{prefill}}(v + t)$$</div>\n<p>其中 <span>T_enc</span> 是纯视觉算力、与文本长度无关；<span>T_prefill</span> 是解码器对视觉前缀加文本指令的一次性前向，跨模态注意力在此阶段读取全部视觉 KV。分辨率档位抬高 <span>v</span>，两项同时上升，且 <span>T_prefill</span> 中的注意力项随 <span>v</span> 增长而非线性（注意力对前缀长度的依赖）。这就是材料所说“把视觉 token 当作普通文本 token 处理会低估预填算力峰值”的机理：视觉前缀在预填阶段是一次性大块算力，而非解码阶段逐 token 摊薄。</p>\n<p>TPOT（每输出 token 时间）的主导项不同：解码阶段视觉 KV 不再变化但持续占位，每步注意力需读取 <span>v + t + 已生成</span> 个 KV 位置，因此 TPOT 随 <span>v</span> 缓慢上升，主要受 KV 带宽而非算力约束。吞吐则由 <span>B</span> 与 <span>M_batch</span> 共同决定：在显存上限内，吞吐近似与批内总 token 数成正比，但受最长前缀请求的块粒度拖累。显存的主项是视觉 KV 常驻占用，材料明确“视觉 KV 全程常驻显存”“显存增量与视觉 token 数成正比”。功耗材料未给出任何数据，只能定性：预填阶段是算力峰值段，功耗峰值出现在 TTFT 窗口而非解码稳态。</p>\n<p>具体例子：同一模型、同一分辨率下，把 batch 从 1 提到 8，TTFT 因预填并行而略升（单批预填 token 总量变大），TPOT 因批内并行而下降，吞吐上升；但若这 8 个请求的 <span>v_i</span> 方差大，<span>M_batch</span> 上界被最长者拉高，实际可容纳 batch 可能远小于 8。这说明“吞吐提升”必须连同 batch 与分桶策略一起报，否则不可比。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-47\">四十七 · 哪些提升不可比：四类常见误读</h3>\n<p>第一类，分辨率档位不同的对比。视觉 token 数由预处理分辨率与 patch 网格决定，分辨率一变，<span>v</span> 变、KV 占用变、预填算力变，三项同时移动。把高分辨率基线与低分辨率改进版对比，得到的“延迟下降”混合了分辨率降级与算法改进两个因子，本文没有提供分离这两者的消融，故不可比。</p>\n<p>第二类，预填/解码口径不同的对比。TTFT 是否包含图像预处理与编码器前向、是否包含排队等待，直接改变数值。材料把 TTFT 归因于“编码前向与预填阶段”，但未规定是否计入预处理，因此跨报告的 TTFT 必须先对齐口径再比较。</p>\n<p>第三类，量化档位不同的对比。材料明确“量化若作用于视觉 KV 或投影层权重，数值误差会传导到跨模态注意力输出”，但未给出精度档位与误差数据。这意味着任何“低精度下吞吐提升”的报告都无法在本文框架内评估其精度代价，属于单边指标，不可比。</p>\n<p>第四类，批调度策略不同的对比。分桶粒度、准入策略、KV 块回收时机都会改变 <span>M_batch</span> 的实际利用率。两个报告若分桶策略不同，其吞吐差异可能完全来自调度而非模型，本文未给出调度细节，故不可比。</p>\n<p>工程判断：在本文口径下，唯一可安全横向传递的量是<strong>结构量</strong>——视觉 token 数 <span>v</span>、单 token KV 字节数 <span>s_kv</span>、层数 <span>L</span>、批内前缀方差。任何速率量（tokens/s、ms/token）都必须附带分辨率、batch、并发、精度、调度五项标签才具备可比性。缺一项即降级为个案观察。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-48\">四十八 · 容量规划的可用算式与监控项</h3>\n<p>材料允许的容量规划只有线性关系估算：“容量规划只能依据视觉 token 数与序列长度的线性关系估算”。据此，单请求常驻显存的下界为</p>\n<div class=\"formula\">$$M_{\\text{req}} \\ge s_{\\text{kv}} \\cdot v \\cdot L + M_{\\text{weights}}$$</div>\n<p>其中 <span>M_weights</span> 含投影层与语言模型权重（视觉编码器是否常驻材料未说明，按冻结编码器可外置处理）。服务可容纳并发数 <span>N</span> 的上界近似为 <span>M_total / M_req</span>，但实际受批内方差与块粒度折损，故真实并发低于该上界。这个折损系数本文未给出，只能由部署方用监控数据标定。</p>\n<p>监控项按材料可直接落地四项：视觉 token 数（按请求分布，看方差而非均值）、预填耗时（分离编码前向与解码器预填两段）、KV 占用（区分视觉前缀常驻与文本增量）、批内长度方差（作为分桶效果的代理指标）。材料明确“材料未给出阈值”，故阈值必须由 SLO 反推：给定 TTFT 目标，用上面的 TTFT 三段式反解可接受的最大 <span>v</span>，再据此设定分辨率档位上限与准入规则。</p>\n<p>具体例子：若 SLO 要求 TTFT 不超过某值，而监控显示预填段占主导且随 <span>v</span> 增长，则分辨率档位应作为准入旋钮而非模型超参——超限请求要么降分辨率、要么排队到低负载窗口。这是本文机制能支撑的最具体的工程动作，其余数值均需现场标定。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-49\">四十九 · 读数的落点：把“提升”还原为结构量</h3>\n<p>本文的性能段落之所以“空”，是因为它把可测量的东西留在了接口层：视觉 token 数、投影层输出维度、KV 常驻、预填一次性算力、批内方差。这五项是任何后续报告都必须交代的结构量，也是判断一个“提升”是否可比的唯一抓手。工程读者应养成一个习惯：看到多模态推理的加速数字，先把它还原成这五项的变化，再看速率量是否在同口径下测得。若还原后结构量未变而速率量变了，那变化来自硬件、调度或测量口径，不属于本文机制范畴；若结构量变了（例如 <span>v</span> 下降），则必须同时追问精度代价与分辨率档位，因为材料明确量化误差会传导到跨模态注意力输出而本文未给误差数据。</p>\n<p>最终落在一条可执行的判断上：在 Blackwell 上部署该范式时，先把 <span>s_kv · v · L</span> 作为显存预算的第一项锁定，再据此反推分辨率档位与分桶粒度，最后才谈吞吐目标；任何跳过这一步直接引用外部吞吐数字的做法，都会把不可比的提升误当作容量依据。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-50\">五十 · 视觉前缀的计量口径：哪些数字能横向读，哪些不能</h3>\n<p>本方案没有内置视觉 token 压缩或合并机制，因此任何跨方案比较都必须先对齐“视觉前缀长度”这一口径。设预处理分辨率为 $R$、patch 网格边长为 $g$，则单请求视觉 token 数 $N_v \\propto (R/g)^2$；KV 增量近似为 $M_{\\mathrm{kv}} = 2 \\cdot L \\cdot d \\cdot N_v \\cdot b$（$L$ 为解码器层数、$d$ 为投影层输出维度、$b$ 为每元素字节数）。投影层输出维度直接决定单 token 显存增量，分辨率翻倍则 $N_v$ 约四倍增长。所以“某方案吞吐提升 X 倍”若未标注分辨率档位与 $N_v$，与另一方案的数字不可比——差异可能全部来自预处理降采样，而非调度或量化本身。</p>\n<p>硬件档位与 batch 口径同样不可省略。材料未给出部署硬件、并行拓扑与量化档位，因此无法把任何指标绑定到 B200/B300 或 GB200 NVL72 的具体配置。可读的只有结构性关系：预填阶段一次性处理全部视觉 token，TTFT 由视觉编码器前向加预填主导；TPOT 阶段视觉 KV 不再变化但持续占位，故 TPOT 对 $N_v$ 不敏感而对批内并发敏感。吞吐必须同时报告并发数与批内图文长度方差，否则长短请求混批带来的显存碎片会把均值吞吐抬高、尾延迟恶化，两个数字互相掩盖。</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>主要受控于</th><th>跨方案可比的前提</th></tr></thead><tbody><tr><td>TTFT</td><td>编码器前向 + 预填算力，随 $N_v$ 上升</td><td>分辨率档位、patch 网格、硬件档位一致</td></tr><tr><td>TPOT</td><td>解码阶段批内并发与 KV 带宽</td><td>并发数、批内长度方差一致</td></tr><tr><td>显存</td><td>$N_v \\times d \\times L$ 常驻 KV</td><td>投影层维度与精度字节数一致</td></tr><tr><td>功耗</td><td>预填峰值算力占比</td><td>需标注是否含编码器独立前向</td></tr></tbody></table>\n<p>失效条件集中在三处。其一，把视觉 token 当普通文本 token 估算预填开销，会低估算力峰值，TTFT 超标却找不到原因；其二，忽略批内视觉前缀长度方差直接混批，显存碎片与尾延迟同时恶化，按视觉 token 数分桶是必要而非可选；其三，在缺少量化误差数据时套用低精度视觉 KV 或投影层权重，误差经跨模态注意力逐层传导，对齐质量下降无法从材料中核验。因此本节的工程判断是：任何性能数字必须附带分辨率、$N_v$、并发、精度四项标注，缺一项即视为不可比，容量规划只按 $N_v$ 与序列长度的线性关系保守估算。</p>\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-51\">五十一 · 迁移到非冻结编码器时的接口重写</h3>\n<p>本范式可迁移性的第一道门槛不在解码器，而在投影层与编码器之间的耦合关系。原方案里编码器冻结、投影层可训练，推理时视觉特征分布稳定，投影层输出可以视为一张固定的映射表；一旦迁移到端到端微调或部分解冻编码器的模型，投影层的输入分布随编码器权重漂移，推理侧就必须把投影层当作随模型版本一起发布的“版本化算子”，而不能像原方案那样把它当作可独立替换的轻量适配器。工程上的具体改法是：把投影层输出维度与词嵌入维度绑定为编译期常量，在服务启动时校验两者一致，否则拒绝加载权重；同时把视觉 token 的数值范围检查（投影后逐通道的均值与方差）纳入预热流程，一旦偏离校准区间就回退到高精度路径。</p>\n<div class=\"formula\">$$\\mathbf{H}_{v}=\\mathrm{Proj}\\big(\\mathrm{Enc}(\\mathbf{X}_{\\mathrm{img}})\\big),\\quad \\dim(\\mathbf{H}_{v})=\\dim(\\mathbf{E}_{\\mathrm{tok}})$$</div>\n<p>代价落在预填阶段：投影层若被合并进编码器尾部，视觉前向的算力峰值会与文本预填串行叠加，首 token 延迟不再由单一阶段主导，而是两段前向的加和。举例来说，把该方案迁到一个编码器与语言模型联合微调的视觉问答模型上，若仍按“编码器前向 + 投影 + 预填”三段串行排布，预填阶段的显存峰值会同时容纳编码器激活与视觉 KV，单请求显存占用高于原方案；把投影层融合进编码器最后一层、让视觉 token 在编码器内部就完成维度对齐，可以省掉一次中间张量落盘，但会让编码器前向的寄存器压力上升，需要重新做 tile 划分。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-52\">五十二 · 迁到高分辨率与视频输入时的前缀膨胀</h3>\n<p>视觉 token 数量由预处理分辨率与 patch 网格决定，这条线性关系是该方案最硬的规模上限。迁到文档理解、遥感或视频帧序列这类高分辨率、多帧输入时，视觉前缀长度按帧数与每帧 patch 数相乘增长，KV cache 占用与跨模态注意力算力同步线性上升，而解码器每层的注意力读取视觉 KV 的成本并不随文本长度摊薄。具体机制上，预填阶段要一次性把全部视觉 token 写入 KV cache，这段写入的带宽开销与 token 数成正比；解码阶段视觉 KV 常驻，显存带宽被持续占用但不再产生新信息，属于纯占位成本。</p>\n<div class=\"formula\">$$N_{v}=N_{f}\\cdot\\frac{H\\cdot W}{p^{2}},\\quad M_{\\mathrm{KV}}\\propto N_{v}\\cdot d_{\\mathrm{head}}\\cdot L$$</div>\n<p>工程判断是：该方案本身不内置视觉 token 压缩或合并机制，迁到高分辨率场景必须外挂前缀裁剪策略，否则容量规划只能按最坏分辨率预留显存，批大小被单请求峰值锁死。一个具体例子是把该方案迁到多页文档问答：每页按固定网格切 patch，十页输入产生的视觉 token 数是单页的十倍，若按单页请求的批大小配置服务，十页请求到达时要么排队要么触发显存回收，尾延迟由最长前缀请求决定。可行的改法是在预处理阶段按页面内容密度做非均匀网格，或在投影层之后按注意力显著性做前缀合并，但这两条都会改变投影层输出的语义分布，需要重新校准。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-53\">五十三 · 迁到低精度与量化路径时的误差传导</h3>\n<p>量化若作用于视觉 KV 或投影层权重，数值误差会沿跨模态注意力传导到输出，而材料未给出精度档位与误差数据，这意味着迁移时不能假设低精度方案可以直接套用。机制上，投影层把视觉特征压到词嵌入维度，这一映射本身是有损的；再叠加视觉 KV 的低精度存储，跨模态注意力在读取视觉 KV 时引入的量化噪声会与文本 KV 的噪声不同源，两者在 softmax 归一化后混合，误差不再可加。工程上的具体做法是把视觉 KV 与文本 KV 的精度策略分开配置：视觉 KV 走较高精度档位、文本 KV 走低精度档位，用显存换对齐稳定性；或者对投影层权重做逐通道缩放，把输出动态范围压到量化区间内。</p>\n<p>代价是显存与带宽的不对称：视觉 KV 占精度高位会吃掉原本用于增大批大小的显存预算，而视觉前缀恰恰是批内最占位的部分。举例来说，迁到一个已经对语言模型做低比特量化的服务栈上，若把视觉 KV 也压到同一档位，跨模态注意力的输出分布偏移无法从材料中核验，只能靠线上指标（回答与图像内容的一致性抽检）兜底；更稳的工程判断是保留视觉 KV 的高精度副本、仅在解码器读取时做即时反量化，用带宽换数值稳定，代价是每层注意力多一次反量化指令。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-54\">五十四 · 迁到分离式预填/解码与多模态批调度</h3>\n<p>该方案的视觉 KV 全程常驻显存，这条性质与分离式预填/解码架构存在结构性摩擦。分离式架构把预填与解码拆到不同节点，预填节点产出 KV 后经高速互联传给解码节点；视觉 KV 体积大、生命周期长，传输成本按 token 数线性增长，而视觉前缀在解码阶段不再变化，属于“传一次、用全程”的数据。具体机制上，迁移时需要把视觉 KV 的传输与文本 KV 的传输分开调度：视觉 KV 走一次性批量传输并在解码节点常驻，文本 KV 走流式增量传输；若两者混在同一通道，视觉前缀的突发传输会阻塞后续请求的文本 KV 增量，抬高解码侧的首 token 等待。</p>\n<div class=\"formula\">$$T_{\\mathrm{ttft}}\\approx T_{\\mathrm{enc}}+T_{\\mathrm{proj}}+T_{\\mathrm{prefill}}(N_{v}+N_{t})+T_{\\mathrm{xfer}}(N_{v})$$</div>\n<p>批调度侧的迁移改动是按视觉 token 数分桶，这一点在原方案里是建议、在分离式架构里是必需：批内视觉前缀长度方差直接决定解码节点的显存碎片程度，长短请求混批会让短请求的 KV 块被长请求的视觉前缀挤到非连续区域，回收时产生碎片。一个具体例子是把该方案迁到图文混合的在线服务：同一批里既有单图短问答、又有多图长文档，若不分桶，解码节点的显存分配器会在长前缀请求结束后留下无法复用的空洞，下一批短请求被迫等待整理；按视觉 token 数分三档桶、每桶独立配额，可以把尾延迟从最长前缀请求解耦出来。</p>\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-55\">五十五 · 规模上限与不适用的边界</h3>\n<p>该方案的规模上限由三条线性关系共同决定：视觉 token 数随分辨率与帧数线性增长、KV 占用随视觉 token 数线性增长、预填算力随视觉 token 数线性增长。三条线叠加的结果是单请求显存与首 token 延迟都随输入规模线性恶化，而解码阶段的吞吐并不因视觉前缀变长而提升，于是单位显存的有效吞吐随输入规模下降。工程判断是：该方案适合视觉前缀长度可控、批内长度方差可管理的场景，不适合把超高分辨率或长视频直接灌入单请求的场景——后者需要外挂压缩、分帧检索或前缀合并，而这些机制不在本范式内。</p>\n<p>不适用的边界还有一条：把视觉 token 当作普通文本 token 处理会低估预填阶段的算力峰值。视觉 token 在预填时全部参与注意力，其算力峰值与文本预填不在同一量级，若调度器按文本 token 的预填成本估算准入，首 token 延迟会超标。迁移到任何新模型或新领域时，第一件要改的不是模型结构，而是把视觉 token 数纳入准入与分桶的显式维度；第二件是校验投影层输出维度与词嵌入维度的一致性；第三件是为视觉 KV 单独设定精度与回收策略。这三件事做完，该方案才能在别的模型上保持可预测的延迟与显存表现，否则规模一上去，线性关系就会以尾延迟和显存碎片的形式暴露出来。</p>\n\n\n<h3 id=\"paper-visual-instruction-tuning-2023-sec-56\">五十六 · 迁移边界：视觉前缀方案在哪些模型与领域会失效</h3>\n<p>这套方案的可迁移性来自一个很窄的接口：视觉 token 与词嵌入同维、同序列、同 KV cache。凡是能保持这个接口的模型，迁移成本主要落在投影层重训与分辨率档位重标定；凡是破坏这个接口的模型，迁移就不是调参而是改造。判断标准可以写成一条准入式：设视觉 token 数为 <span class=\"formula\">$$N_v=\\frac{H\\cdot W}{p^2}$$</span>（H、W 为预处理分辨率，p 为 patch 边长），则单请求视觉 KV 字节数为 <span class=\"formula\">$$M_v=2\\cdot N_v\\cdot L\\cdot d\\cdot b$$</span>（L 为解码器层数，d 为 KV 头维总和，b 为每元素字节数，系数 2 指 K 与 V）。这条式子说明迁移时真正要重算的是三个量：分辨率决定的 N_v、目标模型决定的 L·d、量化档位决定的 b。三者任一变化，容量规划就要重做，而不是沿用原模型的批大小。</p>\n<p>第一类失效发生在解码器结构不共享 KV 语义的模型上：若目标模型采用跨层共享 KV、线性注意力或状态空间主干，视觉 token 不再是“常驻前缀”，而是被压缩进固定状态，此时按 N_v 线性估算显存的做法直接失真，预填阶段也不再是一次性处理全部视觉 token。第二类失效发生在视觉编码器与语言模型对齐假设不成立时：投影层把视觉特征映射到词嵌入空间，前提是编码器输出语义可分；换成医学影像、遥感多光谱、工业缺陷图这类分布外输入，冻结编码器的 patch 特征与词表语义的对应关系变弱，投影层重训只能恢复部分对齐，跨模态注意力会退化为对纹理的浅层匹配。第三类失效是分辨率驱动的规模上限：N_v 随分辨率平方增长，而预填算力与首 token 延迟随 N_v 线性增长，KV 占用也线性增长，因此在固定显存预算下存在一个硬上限——当 N_v 超过批内可用 KV 块容量时，只能降分辨率或减批，二者都以吞吐为代价。该范式未内置视觉 token 压缩或合并机制，高分辨率场景必须外挂前缀裁剪策略，否则上限由显存而非算力决定。</p>\n<p>领域迁移的系统代价要按链路分段核算，而不是只看模型精度。下表给出四类目标场景的改动点与主要代价，均为定性判断，材料未给出任何量化数字。</p>\n<table class=\"mini\"><thead><tr><th>目标场景</th><th>必须改动</th><th>主要代价</th><th>不适用条件</th></tr></thead><tbody><tr><td>同架构换语言模型</td><td>重训投影层、重标定分辨率档位</td><td>投影层输出维度变化导致单 token KV 增量变化，批大小需重算</td><td>目标模型 KV 布局与头维不兼容时</td></tr><tr><td>高分辨率专业图像</td><td>外挂视觉 token 裁剪或合并、分桶更细</td><td>预填算力峰值抬高首 token 延迟，KV 常驻挤压并发</td><td>无压缩机制且显存预算固定时</td></tr><tr><td>视频或多帧输入</td><td>按帧展开视觉前缀、时序位置编码改造</td><td>N_v 随帧数倍增，KV 占用与批内方差同时恶化</td><td>帧间冗余未压缩时上限极低</td></tr><tr><td>低精度部署</td><td>视觉 KV 与投影层权重的量化策略单独标定</td><td>数值误差经跨模态注意力传导，对齐质量无法从材料核验</td><td>缺少误差数据时不应直接套用</td></tr></tbody></table>\n<p>工程判断应落在准入与监控两件事上。准入侧，按 N_v 与文本长度做二维分桶，把视觉前缀长度方差大的请求隔离，避免长短混批造成显存碎片与尾延迟；对超过显存预算的请求在预处理阶段降分辨率，而不是在预填阶段失败重试。监控侧必须采集视觉 token 数、预填耗时、KV 占用与批内长度方差四项，前三项决定容量，第四项决定调度策略是否需要拆分批次。迁移到新模型时，先验证投影层输出维度与目标词嵌入维度一致、视觉 KV 与文本 KV 使用同一分块分配器，再谈吞吐；这两条不成立，方案的可迁移性就到此为止，剩下的工作是改解码器接口而非调批大小。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 121\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Visual Instruction Tuning</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"65.5\" x2=\"271.0\" y2=\"65.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 61.0 L 270.0 70.0 L 278.0 65.5 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"65.5\" x2=\"515.0\" y2=\"65.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 61.0 L 514.0 70.0 L 522.0 65.5 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"111.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2023 · arXiv preprint</text></svg><figcaption><b>家谱</b> · Visual Instruction Tuni… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体评测数据集名称与规模</td></tr><tr><td>基线</td><td>材料未给出对照基线模型与配置</td></tr><tr><td>主要结果</td><td>材料未给出任何吞吐、延迟、显存或精度数字，无法量化视觉 token 压缩比…</td></tr><tr><td>消融</td><td>材料未给出消融实验设置与结果，无法比较投影层结构、分辨率档位与量化方案对推…</td></tr><tr><td>局限</td><td>材料未给出失败模式与监控指标的具体数据；可推断的工程限制是视觉 token…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-visual-instruction-tuning-2023 · 共 9 个片段</p>\n";break;}}})();
